const g=3,n="cong-nghe",i="Công nghệ lớp 3",h="internal",t="bvkp-8b66be785159",c=[{id:"tu-nhien-cong-nghe",title:"Tự nhiên và Công nghệ",lessons:[{id:"cn3-tu-nhien-cong-nghe",title:"Tự nhiên và Công nghệ",weeks:[1,2],learn:[{title:"Đối tượng tự nhiên",text:"Những thứ có sẵn trong tự nhiên, không do con người làm ra, là đối tượng tự nhiên.",example:"🌳 cây  ·  🏞️ sông  ·  ⛰️ núi  ·  ☀️ Mặt Trời"},{title:"Sản phẩm công nghệ",text:"Những đồ vật do con người làm ra để phục vụ cuộc sống là sản phẩm công nghệ.",example:"🪑 ghế  ·  🚲 xe đạp  ·  💡 bóng đèn"},{title:"Từ tự nhiên đến sản phẩm",text:"Con người lấy nguyên liệu từ tự nhiên để làm ra sản phẩm công nghệ.",example:"🌲 gỗ ➜ 🪑 bàn ghế  ·  🧱 đất sét ➜ gạch"}],practice:[{questions:[{id:"cn3-tu-nhien-cong-nghe-01",type:"mc",q:"Đâu là đối tượng tự nhiên?",emoji:"🌳",explain:"Cây bàng có sẵn trong tự nhiên, không do con người làm ra.",options:["Cây bàng","Cái bàn","Quạt điện","Xe đạp"],answer:0},{id:"cn3-tu-nhien-cong-nghe-02",type:"mc",q:"Đâu là sản phẩm công nghệ?",emoji:"💡",explain:"Bóng đèn do con người làm ra nên là sản phẩm công nghệ.",options:["Dòng sông","Bóng đèn","Ngọn núi","Con mèo"],answer:1},{id:"cn3-tu-nhien-cong-nghe-03",type:"tf",q:"Mặt Trời là sản phẩm công nghệ.",emoji:"☀️",explain:"Sai. Mặt Trời có sẵn trong tự nhiên, con người không làm ra được.",answer:!1},{id:"cn3-tu-nhien-cong-nghe-04",type:"tf",q:"Chiếc xe đạp do con người làm ra.",emoji:"🚲",explain:"Đúng. Xe đạp là sản phẩm công nghệ do con người làm ra.",answer:!0},{id:"cn3-tu-nhien-cong-nghe-05",type:"match",q:"Nối đồ vật với việc nó giúp con người.",explain:"Mỗi sản phẩm công nghệ giúp con người một việc trong cuộc sống.",pairs:[["Quạt điện","Làm mát"],["Đèn học","Chiếu sáng"],["Nồi cơm điện","Nấu cơm"]]},{id:"cn3-tu-nhien-cong-nghe-06",type:"multi",q:"Chọn các đối tượng tự nhiên.",explain:"Con sông và hòn đá có sẵn trong tự nhiên; cái ghế và ô tô do con người làm ra.",options:["Con sông","Cái ghế","Hòn đá","Ô tô"],answers:[0,2]},{id:"cn3-tu-nhien-cong-nghe-07",type:"fill",q:"Cái quạt điện do con … làm ra.",explain:"Quạt điện do con người làm ra nên là sản phẩm công nghệ.",answer:["người"]},{id:"cn3-tu-nhien-cong-nghe-08",type:"mc",q:"Con người làm ra vật nào sau đây?",emoji:"🏠",explain:"Ngôi nhà do con người xây nên; cầu vồng và mây có sẵn trong tự nhiên.",options:["Cầu vồng","Mây trắng","Ngôi nhà"],answer:2},{id:"cn3-tu-nhien-cong-nghe-09",type:"tf",q:"Cây bàng trong sân trường là đối tượng tự nhiên.",emoji:"🌳",explain:"Đúng. Cây cối là đối tượng tự nhiên.",answer:!0}]},{questions:[{id:"cn3-tu-nhien-cong-nghe-10",type:"match",q:"Nối sản phẩm với nguyên liệu lấy từ tự nhiên.",explain:"Con người lấy nguyên liệu từ tự nhiên để làm ra sản phẩm.",pairs:[["Bàn gỗ","Cây gỗ"],["Viên gạch","Đất sét"],["Áo vải bông","Cây bông"]]},{id:"cn3-tu-nhien-cong-nghe-11",type:"mc",q:"Vì sao cái bàn là sản phẩm công nghệ?",emoji:"🪑",explain:"Cái bàn do con người làm ra nên là sản phẩm công nghệ.",options:["Vì có sẵn từ lâu","Vì nó rất cứng","Do người làm ra"],answer:2},{id:"cn3-tu-nhien-cong-nghe-12",type:"mc",q:"Cái bàn gỗ được làm từ nguyên liệu nào?",emoji:"🪵",explain:"Bàn gỗ làm từ gỗ của cây.",options:["Đất sét","Cát","Cây gỗ","Lông cừu"],answer:2},{id:"cn3-tu-nhien-cong-nghe-13",type:"tf",q:"Mọi đồ vật trong nhà đều có sẵn trong tự nhiên.",explain:"Sai. Nhiều đồ vật trong nhà do con người làm ra, như bàn, ghế, quạt.",answer:!1},{id:"cn3-tu-nhien-cong-nghe-14",type:"multi",q:"Chọn các sản phẩm công nghệ.",explain:"Máy giặt, tủ lạnh, xe máy do con người làm ra; con bò và bông hoa là tự nhiên.",options:["Máy giặt","Con bò","Tủ lạnh","Bông hoa","Xe máy"],answers:[0,2,4]},{id:"cn3-tu-nhien-cong-nghe-15",type:"mc",q:"Sản phẩm công nghệ nào giúp em đi học nhanh hơn?",emoji:"🚲",explain:"Xe đạp giúp em đi lại nhanh hơn đi bộ.",options:["Cái chổi","Cái thìa","Bút chì","Xe đạp"],answer:3},{id:"cn3-tu-nhien-cong-nghe-16",type:"tf",q:"Con người dùng nguyên liệu từ tự nhiên để làm ra sản phẩm công nghệ.",explain:"Đúng. Ví dụ gỗ làm bàn ghế, đất sét làm gạch.",answer:!0},{id:"cn3-tu-nhien-cong-nghe-17",type:"mc",q:"Làn gió thổi từ cánh đồng thuộc nhóm nào?",emoji:"🌾",explain:"Gió ngoài cánh đồng có sẵn trong tự nhiên.",options:["Sản phẩm công nghệ","Đối tượng tự nhiên"],answer:1},{id:"cn3-tu-nhien-cong-nghe-18",type:"mc",q:"Đồ vật nào giúp tạo ra gió mát khi trời nóng?",explain:"Quạt điện do con người làm ra để tạo gió mát.",options:["Tủ sách","Cái cốc","Quạt điện"],answer:2}]},{questions:[{id:"cn3-tu-nhien-cong-nghe-19",type:"mc",q:"Trời tối, An muốn đọc sách. An cần sản phẩm nào?",emoji:"📖",explain:"Đèn học chiếu sáng giúp An đọc sách khi trời tối.",options:["Quạt giấy","Đèn học","Cái ô"],answer:1},{id:"cn3-tu-nhien-cong-nghe-20",type:"mc",q:"Nam muốn biết giờ để không đi học muộn. Nam dùng gì?",emoji:"⏰",explain:"Đồng hồ cho Nam biết giờ.",options:["Đồng hồ","Cái bát","Cây chổi","Cái gối"],answer:0},{id:"cn3-tu-nhien-cong-nghe-21",type:"multi",q:"Sản phẩm công nghệ nào giúp nhà cửa sạch sẽ?",explain:"Máy hút bụi, chổi, máy giặt do con người làm ra và giúp nhà sạch sẽ.",options:["Máy hút bụi","Cái chổi","Bông hoa","Máy giặt","Đám mây"],answers:[0,1,3]},{id:"cn3-tu-nhien-cong-nghe-22",type:"order",q:"Sắp xếp quá trình làm ra cái bàn gỗ.",explain:"Người thợ lấy gỗ, cưa bào, ghép lại rồi sơn để có cái bàn.",items:["Lấy gỗ từ cây","Cưa, bào gỗ","Ghép thành bàn","Sơn cho đẹp"]},{id:"cn3-tu-nhien-cong-nghe-23",type:"tf",q:"Con người cần bảo vệ tự nhiên vì tự nhiên cho ta nhiều nguyên liệu.",explain:"Đúng. Gỗ, đất, nước… đều từ tự nhiên, cần được giữ gìn.",answer:!0},{id:"cn3-tu-nhien-cong-nghe-24",type:"tf",q:"Chiếc thuyền gỗ là sản phẩm công nghệ, dù làm từ gỗ của cây.",emoji:"🛶",explain:"Đúng. Gỗ là tự nhiên, nhưng con người đóng thành thuyền nên thuyền là sản phẩm công nghệ.",answer:!0},{id:"cn3-tu-nhien-cong-nghe-25",type:"match",q:"Nối nhu cầu với sản phẩm công nghệ giúp em.",explain:"Con người làm ra sản phẩm công nghệ để đáp ứng nhu cầu của mình.",pairs:[["Trời nóng","Quạt điện"],["Trời tối","Bóng đèn"],["Muốn nghe tin","Máy thu thanh"],["Đi xa","Ô tô"]]},{id:"cn3-tu-nhien-cong-nghe-26",type:"fill",q:"Đồ vật do con người làm ra gọi là sản phẩm công … .",explain:"Đồ vật do con người làm ra là sản phẩm công nghệ.",answer:["nghệ"]}]}],challenge:{questions:[{id:"cn3-tu-nhien-cong-nghe-27",type:"mc",q:"Nhóm nào toàn là sản phẩm công nghệ?",explain:"Bàn, ghế, quạt đều do con người làm ra.",options:["Cây, bàn, mây","Sông, núi, đèn","Bàn, ghế, quạt"],answer:2},{id:"cn3-tu-nhien-cong-nghe-28",type:"mc",q:"Nhóm nào toàn là đối tượng tự nhiên?",explain:"Mưa, nắng, gió đều có sẵn trong tự nhiên.",options:["Đèn, mưa, gió","Mưa, nắng, gió","Ti vi, đá, cát"],answer:1},{id:"cn3-tu-nhien-cong-nghe-29",type:"multi",q:"Chọn các nguyên liệu lấy từ tự nhiên.",explain:"Gỗ, đất sét, cát có trong tự nhiên; bút bi và ti vi là sản phẩm công nghệ.",options:["Gỗ","Đất sét","Bút bi","Cát","Ti vi"],answers:[0,1,3]},{id:"cn3-tu-nhien-cong-nghe-30",type:"tf",q:"Sản phẩm công nghệ chỉ có ở thành phố, không có ở nông thôn.",explain:"Sai. Ở đâu cũng có sản phẩm công nghệ, như cái cuốc, xe đạp, bóng đèn.",answer:!1},{id:"cn3-tu-nhien-cong-nghe-31",type:"mc",q:"Cái rổ đan bằng tre thuộc nhóm nào?",emoji:"🧺",explain:"Tre là tự nhiên, nhưng cái rổ do con người đan nên là sản phẩm công nghệ.",options:["Đối tượng tự nhiên","Sản phẩm công nghệ"],answer:1},{id:"cn3-tu-nhien-cong-nghe-32",type:"order",q:"Sắp xếp quá trình làm ra viên gạch.",explain:"Đất sét được nhào, đóng khuôn, phơi khô rồi nung thành gạch.",items:["Lấy đất sét","Nhào và đóng khuôn","Phơi khô","Nung trong lò"]},{id:"cn3-tu-nhien-cong-nghe-33",type:"match",q:"Nối sản phẩm với nguyên liệu chính.",explain:"Thủy tinh làm từ cát, giấy làm từ gỗ, rổ đan từ tre.",pairs:[["Cốc thủy tinh","Cát"],["Giấy viết","Gỗ"],["Rổ đan","Tre"]]}]},summary:["Đối tượng tự nhiên có sẵn trong tự nhiên, không do con người làm ra.","Sản phẩm công nghệ do con người làm ra để phục vụ cuộc sống.","Con người dùng nguyên liệu từ tự nhiên để làm ra sản phẩm công nghệ."]},{id:"cn3-san-pham-cong-nghe",title:"Sản phẩm công nghệ trong gia đình",weeks:[3,4],learn:[{title:"Nhà em có nhiều sản phẩm công nghệ",text:"Trong nhà có ti vi, tủ lạnh, quạt, nồi cơm điện, máy giặt, bóng đèn và nhiều đồ dùng khác.",example:"📺  ❄️  🌀  🍚  💡"},{title:"Mỗi đồ dùng một công dụng",text:"Tủ lạnh giữ thức ăn tươi lâu, máy giặt giặt quần áo, nồi cơm điện nấu cơm.",example:"❄️ giữ lạnh  ·  👕 giặt  ·  🍚 nấu cơm"},{title:"Dùng điện và không dùng điện",text:"Có đồ dùng cần điện để chạy, có đồ dùng không cần điện.",example:"🔌 quạt điện, ti vi  ·  ✂️ kéo, 🧹 chổi"}],practice:[{questions:[{id:"cn3-san-pham-cong-nghe-01",type:"mc",q:"Đồ dùng nào giúp giữ thức ăn tươi lâu?",emoji:"🥬",explain:"Tủ lạnh giữ lạnh nên thức ăn tươi lâu hơn.",options:["Quạt điện","Ti vi","Tủ lạnh"],answer:2},{id:"cn3-san-pham-cong-nghe-02",type:"mc",q:"Máy giặt dùng để làm gì?",emoji:"👕",explain:"Máy giặt giúp giặt sạch quần áo.",options:["Nấu cơm","Giặt quần áo","Chiếu sáng","Xem phim"],answer:1},{id:"cn3-san-pham-cong-nghe-03",type:"match",q:"Nối đồ dùng với công dụng.",explain:"Mỗi đồ dùng trong nhà có công dụng riêng.",pairs:[["Nồi cơm điện","Nấu cơm"],["Bóng đèn","Chiếu sáng"],["Ti vi","Xem chương trình"]]},{id:"cn3-san-pham-cong-nghe-04",type:"tf",q:"Nồi cơm điện là sản phẩm công nghệ.",emoji:"🍚",explain:"Đúng. Nồi cơm điện do con người làm ra để nấu cơm.",answer:!0},{id:"cn3-san-pham-cong-nghe-05",type:"tf",q:"Ti vi dùng để giữ lạnh thức ăn.",emoji:"📺",explain:"Sai. Tủ lạnh mới giữ lạnh thức ăn; ti vi dùng để xem.",answer:!1},{id:"cn3-san-pham-cong-nghe-06",type:"multi",q:"Chọn đồ dùng cần điện để hoạt động.",explain:"Quạt điện và ti vi cần điện; chổi và kéo không cần điện.",options:["Quạt điện","Cái chổi","Ti vi","Cái kéo"],answers:[0,2]},{id:"cn3-san-pham-cong-nghe-07",type:"mc",q:"Ấm siêu tốc dùng để làm gì?",explain:"Ấm siêu tốc dùng điện để đun sôi nước nhanh.",options:["Làm đá viên","Đun sôi nước","Giặt quần áo"],answer:1},{id:"cn3-san-pham-cong-nghe-08",type:"fill",q:"Đồ dùng giữ thức ăn lạnh là tủ … .",explain:"Tủ lạnh giữ thức ăn lạnh và tươi lâu.",answer:["lạnh"]},{id:"cn3-san-pham-cong-nghe-09",type:"mc",q:"Đồ dùng nào giúp làm mát căn phòng?",explain:"Máy điều hòa làm mát không khí trong phòng.",options:["Bàn là","Bếp ga","Máy điều hòa"],answer:2}]},{questions:[{id:"cn3-san-pham-cong-nghe-10",type:"multi",q:"Chọn đồ dùng không cần điện.",explain:"Kéo, chổi, thìa dùng bằng tay, không cần điện.",options:["Cái kéo","Máy giặt","Cái chổi","Bàn là điện","Cái thìa"],answers:[0,2,4]},{id:"cn3-san-pham-cong-nghe-11",type:"mc",q:"Mẹ muốn quần áo phẳng, mẹ dùng gì?",explain:"Bàn là làm phẳng quần áo.",options:["Quạt điện","Tủ lạnh","Bàn là"],answer:2},{id:"cn3-san-pham-cong-nghe-12",type:"mc",q:"Vì sao nhà em cần đèn điện?",emoji:"💡",explain:"Đèn điện chiếu sáng khi trời tối.",options:["Để làm mát","Để nấu ăn","Để chiếu sáng"],answer:2},{id:"cn3-san-pham-cong-nghe-13",type:"tf",q:"Chiếc điện thoại có thể dùng để gọi điện và chụp ảnh.",emoji:"📱",explain:"Đúng. Một sản phẩm công nghệ có thể có nhiều công dụng.",answer:!0},{id:"cn3-san-pham-cong-nghe-14",type:"match",q:"Nối đồ dùng với việc làm trong nhà.",explain:"Mỗi đồ dùng giúp gia đình một việc.",pairs:[["Máy hút bụi","Làm sạch sàn"],["Lò vi sóng","Hâm nóng thức ăn"],["Máy sấy tóc","Làm khô tóc"],["Quạt điện","Làm mát"]]},{id:"cn3-san-pham-cong-nghe-15",type:"tf",q:"Cái chổi không phải sản phẩm công nghệ vì nó không dùng điện.",emoji:"🧹",explain:"Sai. Chổi do con người làm ra nên vẫn là sản phẩm công nghệ.",answer:!1},{id:"cn3-san-pham-cong-nghe-16",type:"mc",q:"Sản phẩm nào giúp gia đình nghe tin tức?",emoji:"📻",explain:"Máy thu thanh phát tin tức, ca nhạc cho cả nhà nghe.",options:["Cái bát ăn cơm","Máy thu thanh","Cái gối ôm"],answer:1},{id:"cn3-san-pham-cong-nghe-17",type:"mc",q:"Bình muốn xem phim hoạt hình. Bình dùng gì?",emoji:"📺",explain:"Ti vi cho Bình xem phim hoạt hình.",options:["Tủ lạnh","Ti vi","Ấm điện","Máy giặt"],answer:1},{id:"cn3-san-pham-cong-nghe-18",type:"fill",q:"Máy … quần áo giúp mẹ đỡ vất vả.",explain:"Máy giặt giặt quần áo giúp mẹ đỡ vất vả.",answer:["giặt"]}]},{questions:[{id:"cn3-san-pham-cong-nghe-19",type:"mc",q:"Trời mất điện, đồ dùng nào vẫn dùng được?",emoji:"🪭",explain:"Quạt nan quạt bằng tay nên không cần điện.",options:["Quạt điện","Nồi cơm điện","Ti vi","Quạt nan"],answer:3},{id:"cn3-san-pham-cong-nghe-20",type:"mc",q:"Nhà Lan có cá tươi chưa nấu ngay. Nên cất ở đâu?",emoji:"🐟",explain:"Tủ lạnh giữ cá tươi lâu hơn.",options:["Trong tủ sách","Ngoài nắng","Trong tủ lạnh"],answer:2},{id:"cn3-san-pham-cong-nghe-21",type:"multi",q:"Đồ dùng nào giúp nấu ăn?",explain:"Bếp điện, nồi cơm điện, lò vi sóng dùng trong nấu nướng.",options:["Bếp điện","Nồi cơm điện","Máy giặt","Lò vi sóng","Quạt điện"],answers:[0,1,3]},{id:"cn3-san-pham-cong-nghe-22",type:"tf",q:"Muốn có nước uống mát, có thể để chai nước vào tủ lạnh.",emoji:"🧊",explain:"Đúng. Tủ lạnh làm lạnh chai nước.",answer:!0},{id:"cn3-san-pham-cong-nghe-23",type:"match",q:"Nối tình huống với đồ dùng phù hợp.",explain:"Chọn đồ dùng có công dụng hợp với việc cần làm.",pairs:[["Tóc ướt sau khi gội","Máy sấy tóc"],["Sàn nhà nhiều bụi","Máy hút bụi"],["Quần áo bẩn","Máy giặt"]]},{id:"cn3-san-pham-cong-nghe-24",type:"mc",q:"Vật nào KHÔNG phải sản phẩm công nghệ?",emoji:"🌴",explain:"Cây cau có sẵn trong tự nhiên; các vật còn lại do con người làm ra.",options:["Bàn chải","Cái ghế","Cây cau","Cái ấm"],answer:2},{id:"cn3-san-pham-cong-nghe-25",type:"order",q:"Sắp xếp việc nấu cơm bằng nồi cơm điện.",explain:"Vo gạo, đặt nồi, cắm điện bật nút rồi chờ cơm chín.",items:["Vo gạo, cho nước vào nồi","Đặt lòng nồi vào nồi","Bố mẹ cắm điện, bật nút nấu","Chờ cơm chín"]},{id:"cn3-san-pham-cong-nghe-26",type:"tf",q:"Sản phẩm công nghệ giúp cuộc sống gia đình tiện lợi hơn.",explain:"Đúng. Nhờ các đồ dùng, việc nhà nhanh và nhẹ nhàng hơn.",answer:!0}]}],challenge:{questions:[{id:"cn3-san-pham-cong-nghe-27",type:"mc",q:"Nhóm nào toàn đồ dùng cần điện?",explain:"Quạt điện, ti vi, tủ lạnh đều cần điện để chạy.",options:["Chổi, kéo, bát","Quạt, ti vi, tủ lạnh","Quạt nan, ô, gối"],answer:1},{id:"cn3-san-pham-cong-nghe-28",type:"multi",q:"Đồ dùng nào giúp giữ nhà sạch?",explain:"Máy hút bụi, cây lau nhà, máy giặt giúp nhà cửa, quần áo sạch sẽ.",options:["Máy hút bụi","Cây lau nhà","Máy giặt","Ti vi","Đèn ngủ"],answers:[0,1,2]},{id:"cn3-san-pham-cong-nghe-29",type:"tf",q:"Tủ lạnh dùng để nấu chín thức ăn.",explain:"Sai. Tủ lạnh giữ lạnh thức ăn, không nấu chín.",answer:!1},{id:"cn3-san-pham-cong-nghe-30",type:"mc",q:"Hà muốn tóc khô nhanh sau khi gội. Hà nên làm gì?",explain:"Máy sấy tóc làm khô tóc nhanh; bạn nhỏ nên nhờ người lớn giúp.",options:["Mở cửa tủ lạnh","Đứng ngoài mưa","Nhờ mẹ sấy tóc"],answer:2},{id:"cn3-san-pham-cong-nghe-31",type:"match",q:"Nối đồ dùng với thứ nó cần để hoạt động.",explain:"Quạt điện cần điện, bếp ga cần khí ga, đèn pin cần pin.",pairs:[["Quạt điện","Điện"],["Bếp ga","Khí ga"],["Đèn pin","Pin"]]},{id:"cn3-san-pham-cong-nghe-32",type:"fill",q:"Nồi cơm … giúp nấu cơm nhanh, tiện lợi.",explain:"Nồi cơm điện dùng điện để nấu cơm.",answer:["điện"]},{id:"cn3-san-pham-cong-nghe-33",type:"mc",q:"Lò vi sóng thường dùng để làm gì?",explain:"Lò vi sóng thường dùng để hâm nóng đồ ăn.",options:["Giặt quần áo","Làm mát phòng","Hâm nóng đồ ăn"],answer:2}]},summary:["Gia đình em có nhiều sản phẩm công nghệ như ti vi, tủ lạnh, quạt, nồi cơm điện.","Mỗi sản phẩm công nghệ có công dụng riêng.","Có đồ dùng cần điện, có đồ dùng không cần điện."]},{id:"cn3-giu-gin-san-pham",title:"Giữ gìn sản phẩm công nghệ",weeks:[5,5],learn:[{title:"Dùng đúng cách",text:"Dùng đồ dùng đúng công dụng và đúng hướng dẫn thì đồ dùng bền và an toàn.",example:"📄 đọc hướng dẫn  ·  👍 dùng nhẹ nhàng"},{title:"Giữ sạch, để đúng chỗ",text:"Lau sạch bụi, để nơi khô ráo, dùng xong cất đúng chỗ.",example:"🧽 lau sạch  ·  📦 cất gọn"},{title:"Hỏng thì báo người lớn",text:"Đồ dùng bị hỏng, em báo người lớn. Không tự tháo, tự sửa đồ dùng điện.",example:"🙋 báo bố mẹ  ·  🚫🔧 không tự sửa"}],practice:[{questions:[{id:"cn3-giu-gin-san-pham-01",type:"tf",q:"Chỉ lau đồ dùng điện khi người lớn đã rút phích điện.",emoji:"🔌",explain:"Đúng. Rút điện trước khi lau để tránh bị điện giật.",answer:!0},{id:"cn3-giu-gin-san-pham-02",type:"tf",q:"Đồ dùng điện bị hỏng, em có thể tự tháo ra sửa.",explain:"Sai. Tự sửa đồ điện rất nguy hiểm, em cần báo người lớn.",answer:!1},{id:"cn3-giu-gin-san-pham-03",type:"mc",q:"Dùng xong bút màu, em nên làm gì?",emoji:"🖍️",explain:"Cất bút vào hộp giúp bút không gãy, không mất.",options:["Để dưới sàn","Cất vào hộp","Bẻ làm đôi"],answer:1},{id:"cn3-giu-gin-san-pham-04",type:"mc",q:"Thấy quạt có tiếng kêu lạ, em nên làm gì?",emoji:"🌀",explain:"Quạt kêu lạ có thể bị hỏng, em báo người lớn kiểm tra.",options:["Lấy tay giữ cánh","Đá vào quạt","Báo người lớn"],answer:2},{id:"cn3-giu-gin-san-pham-05",type:"multi",q:"Việc làm nào giúp giữ gìn đồ dùng?",explain:"Dùng đúng cách, để đúng chỗ, lau sạch giúp đồ dùng bền lâu.",options:["Dùng đúng cách","Để đúng chỗ","Ném đồ chơi","Lau sạch bụi"],answers:[0,1,3]},{id:"cn3-giu-gin-san-pham-06",type:"fill",q:"Dùng xong đồ dùng, em cất vào đúng … .",explain:"Cất đúng chỗ giúp đồ dùng bền và dễ tìm.",answer:["chỗ","nơi"]},{id:"cn3-giu-gin-san-pham-07",type:"mc",q:"Vì sao cần giữ gìn sản phẩm công nghệ?",explain:"Giữ gìn giúp đồ dùng bền, dùng được lâu.",options:["Để chúng mau hỏng","Để dùng được lâu","Để vứt đi sớm"],answer:1},{id:"cn3-giu-gin-san-pham-08",type:"tf",q:"Để ti vi ở chỗ khô ráo giúp ti vi bền hơn.",emoji:"📺",explain:"Đúng. Nơi ẩm ướt dễ làm hỏng đồ điện.",answer:!0},{id:"cn3-giu-gin-san-pham-09",type:"match",q:"Nối đồ dùng với cách giữ gìn.",explain:"Mỗi đồ dùng có cách giữ gìn phù hợp.",pairs:[["Sách vở","Bọc bìa, không vẽ bậy"],["Xe đạp","Lau sạch, cất chỗ khô"],["Quạt điện","Lau bụi khi đã rút điện"]]}]},{questions:[{id:"cn3-giu-gin-san-pham-10",type:"mc",q:"Vì sao không nên để ti vi gần chỗ ẩm ướt?",explain:"Hơi ẩm, nước dễ làm hỏng ti vi và gây nguy hiểm.",options:["Xem rõ hơn","Dễ bị hỏng","Đẹp hơn"],answer:1},{id:"cn3-giu-gin-san-pham-11",type:"tf",q:"Dùng sản phẩm đúng hướng dẫn giúp sản phẩm bền và an toàn.",explain:"Đúng. Hướng dẫn cho biết cách dùng đúng.",answer:!0},{id:"cn3-giu-gin-san-pham-12",type:"mc",q:"Đồ chơi chạy pin lâu không dùng, nên làm gì?",emoji:"🔋",explain:"Tháo pin ra để pin không bị chảy nước làm hỏng đồ chơi.",options:["Để ngoài nắng","Ngâm vào nước","Tháo pin ra"],answer:2},{id:"cn3-giu-gin-san-pham-13",type:"multi",q:"Việc làm nào làm đồ dùng mau hỏng?",explain:"Làm rơi và để nơi ẩm làm đồ dùng mau hỏng.",options:["Làm rơi điện thoại","Để sách nơi ẩm","Lau bụi quạt","Cất bút vào hộp"],answers:[0,1]},{id:"cn3-giu-gin-san-pham-14",type:"order",q:"Sắp xếp việc cất đồ chơi sau khi chơi.",explain:"Tắt công tắc, lau sạch rồi cất gọn vào hộp.",items:["Tắt công tắc đồ chơi","Lau sạch đồ chơi","Cất vào hộp"]},{id:"cn3-giu-gin-san-pham-15",type:"tf",q:"Khi mượn đồ của bạn, em cần giữ gìn và trả lại đúng hẹn.",explain:"Đúng. Giữ gìn đồ của bạn cũng như đồ của mình.",answer:!0},{id:"cn3-giu-gin-san-pham-16",type:"mc",q:"Quyển sách bị rách, em làm gì?",emoji:"📘",explain:"Dán lại cẩn thận để sách còn dùng được.",options:["Xé thêm cho vui","Dán lại cẩn thận","Ném vào sọt rác"],answer:1},{id:"cn3-giu-gin-san-pham-17",type:"tf",q:"Bật tắt quạt liên tục cho vui không làm hỏng quạt.",explain:"Sai. Bật tắt liên tục làm quạt mau hỏng.",answer:!1},{id:"cn3-giu-gin-san-pham-18",type:"fill",q:"Đồ dùng điện bị hỏng, em báo cho người … .",explain:"Người lớn sẽ kiểm tra hoặc nhờ thợ sửa an toàn.",answer:["lớn"]}]},{questions:[{id:"cn3-giu-gin-san-pham-19",type:"mc",q:"Minh thấy dây sạc bị hở lõi đồng. Minh làm gì?",explain:"Dây hở lõi có thể gây điện giật, Minh báo bố mẹ ngay.",options:["Báo bố mẹ ngay","Tự quấn băng dính","Tiếp tục dùng"],answer:0},{id:"cn3-giu-gin-san-pham-20",type:"mc",q:"Trước khi lau quạt điện, cần làm gì?",explain:"Phải rút phích điện trước khi lau để an toàn.",options:["Nhờ rút phích điện","Bật số to nhất","Tưới nước lên quạt"],answer:0},{id:"cn3-giu-gin-san-pham-21",type:"multi",q:"Bình muốn giữ xe đạp bền. Bình nên làm gì?",emoji:"🚲",explain:"Lau sạch, bơm đủ hơi, cất nơi khô giúp xe bền.",options:["Lau sạch bùn đất","Để xe dưới mưa","Bơm lốp đủ hơi","Cất xe nơi khô"],answers:[0,2,3]},{id:"cn3-giu-gin-san-pham-22",type:"tf",q:"Lấy khăn ướt lau ổ cắm điện là cách giữ sạch an toàn.",explain:"Sai. Nước dẫn điện, lau ổ điện bằng khăn ướt rất nguy hiểm.",answer:!1},{id:"cn3-giu-gin-san-pham-23",type:"match",q:"Nối việc làm với kết quả.",explain:"Việc làm tốt giúp đồ dùng bền; làm rơi dễ làm hỏng đồ.",pairs:[["Lau bụi thường xuyên","Đồ dùng sạch, bền"],["Làm rơi đồ dùng","Dễ vỡ, hỏng"],["Cất đúng chỗ","Dễ tìm khi cần"]]},{id:"cn3-giu-gin-san-pham-24",type:"mc",q:"Đồ chơi bị gãy một chi tiết nhỏ, em nên làm gì?",explain:"Chi tiết nhỏ ngậm vào miệng rất nguy hiểm; nhờ bố mẹ xem và sửa.",options:["Nhờ bố mẹ xem","Ngậm vào miệng","Ném vào tường"],answer:0},{id:"cn3-giu-gin-san-pham-25",type:"order",q:"Sắp xếp việc cất sách vở sau khi học.",explain:"Gấp sách vở, xếp gọn rồi cất lên giá.",items:["Gấp sách vở lại","Xếp theo thứ tự","Cất lên giá sách"]},{id:"cn3-giu-gin-san-pham-26",type:"tf",q:"Đọc kĩ hướng dẫn trước khi dùng giúp dùng sản phẩm đúng cách.",explain:"Đúng. Hướng dẫn cho biết cách dùng đúng và an toàn.",answer:!0}]}],challenge:{questions:[{id:"cn3-giu-gin-san-pham-27",type:"mc",q:"Đèn học có mùi khét. Việc đầu tiên nên làm là gì?",explain:"Mùi khét là dấu hiệu nguy hiểm, cần báo người lớn ngay.",options:["Ghé sát mũi ngửi","Đổ nước vào đèn","Báo người lớn ngay"],answer:2},{id:"cn3-giu-gin-san-pham-28",type:"multi",q:"Đâu là cách giữ gìn ti vi?",explain:"Lau khăn khô, để chỗ khô, tắt khi không xem giúp ti vi bền.",options:["Lau bằng khăn khô","Đặt chỗ khô ráo","Vẽ bút lên màn","Tắt khi không xem"],answers:[0,1,3]},{id:"cn3-giu-gin-san-pham-29",type:"tf",q:"Đồ dùng đắt tiền mới cần giữ gìn, đồ rẻ thì không cần.",explain:"Sai. Đồ dùng nào cũng cần giữ gìn để dùng lâu.",answer:!1},{id:"cn3-giu-gin-san-pham-30",type:"match",q:"Nối đồ dùng với điều em nên tránh.",explain:"Tránh những việc làm hỏng đồ dùng hoặc gây nguy hiểm.",pairs:[["Bút máy","Làm rơi ngòi"],["Ti vi","Chạm tay ướt"],["Sách","Vẽ bậy"]]},{id:"cn3-giu-gin-san-pham-31",type:"mc",q:"Vì sao không tự sửa đồ dùng điện?",explain:"Tự sửa đồ điện có thể bị điện giật.",options:["Đồ sẽ mới hơn","Sửa rất vui","Dễ bị điện giật"],answer:2},{id:"cn3-giu-gin-san-pham-32",type:"fill",q:"Giữ gìn đồ dùng giúp gia đình tiết kiệm … .",explain:"Đồ dùng bền thì không phải mua mới, tiết kiệm tiền.",answer:["tiền"]},{id:"cn3-giu-gin-san-pham-33",type:"order",q:"Sắp xếp việc làm khi đồ chơi hết pin.",explain:"Tắt đồ chơi, nhờ người lớn thay pin rồi bật thử.",items:["Tắt công tắc đồ chơi","Nhờ người lớn thay pin","Bật lại để thử"]}]},summary:["Dùng đồ dùng đúng cách, đúng hướng dẫn.","Giữ đồ dùng sạch sẽ, để nơi khô ráo, cất đúng chỗ.","Đồ dùng bị hỏng thì báo người lớn, không tự sửa đồ dùng điện."]}]},{id:"do-dung-dien",title:"Sử dụng đồ dùng điện trong gia đình",lessons:[{id:"cn3-den-hoc",title:"Sử dụng đèn học",weeks:[6,7],learn:[{title:"Đèn học giúp gì cho em?",text:"Đèn học chiếu sáng góc học tập, giúp em đọc, viết rõ khi trời tối.",example:"💡📖"},{title:"Các bộ phận của đèn học",text:"Đèn học thường có đế đèn, thân đèn, chụp đèn, bóng đèn, công tắc, dây điện và phích cắm.",example:"🔘 công tắc  ·  💡 bóng đèn  ·  🔌 phích cắm"},{title:"Dùng đèn học đúng cách",text:"Bạn viết tay phải đặt đèn bên trái. Chỉnh chụp đèn chiếu vào trang vở, không chiếu vào mắt. Học xong thì tắt đèn.",example:"✍️ tay phải ➜ 💡 bên trái"}],practice:[{questions:[{id:"cn3-den-hoc-01",type:"mc",q:"Đèn học dùng để làm gì?",emoji:"💡",explain:"Đèn học chiếu sáng giúp em học bài rõ hơn.",options:["Chiếu sáng góc học","Làm mát căn phòng","Phát nhạc cho em"],answer:0},{id:"cn3-den-hoc-02",type:"mc",q:"Bộ phận nào dùng để bật, tắt đèn?",explain:"Em bấm công tắc để bật hoặc tắt đèn.",options:["Đế đèn","Chụp đèn","Công tắc"],answer:2},{id:"cn3-den-hoc-03",type:"mc",q:"Bộ phận nào giúp đèn đứng vững?",explain:"Đế đèn nặng và rộng giúp đèn đứng vững.",options:["Công tắc","Bóng đèn","Đế đèn"],answer:2},{id:"cn3-den-hoc-04",type:"tf",q:"Bóng đèn là bộ phận phát ra ánh sáng.",explain:"Đúng. Khi có điện, bóng đèn phát sáng.",answer:!0},{id:"cn3-den-hoc-05",type:"tf",q:"Chụp đèn dùng để cắm vào ổ điện.",explain:"Sai. Phích cắm mới cắm vào ổ điện; chụp đèn giúp hướng ánh sáng.",answer:!1},{id:"cn3-den-hoc-06",type:"match",q:"Nối bộ phận đèn học với tác dụng.",explain:"Mỗi bộ phận của đèn học có một tác dụng riêng.",pairs:[["Bóng đèn","Phát sáng"],["Đế đèn","Giữ đèn đứng vững"],["Công tắc","Bật, tắt đèn"],["Phích cắm","Nối với ổ điện"]]},{id:"cn3-den-hoc-07",type:"fill",q:"Em bật, tắt đèn bằng công … .",explain:"Công tắc dùng để bật và tắt đèn.",answer:["tắc"]},{id:"cn3-den-hoc-08",type:"multi",q:"Đâu là bộ phận của đèn học?",explain:"Cánh quạt là bộ phận của quạt, không phải của đèn học.",options:["Đế đèn","Bóng đèn","Cánh quạt","Công tắc"],answers:[0,1,3]},{id:"cn3-den-hoc-09",type:"tf",q:"Học xong, em nên tắt đèn học.",explain:"Đúng. Tắt đèn khi không dùng để tiết kiệm điện.",answer:!0}]},{questions:[{id:"cn3-den-hoc-10",type:"mc",q:"Bạn viết tay phải nên đặt đèn ở đâu?",explain:"Đèn bên trái thì bóng của tay phải không che chỗ viết.",options:["Phía bên phải","Sau lưng em","Phía bên trái"],answer:2},{id:"cn3-den-hoc-11",type:"tf",q:"Chụp đèn nên chiếu thẳng vào mắt cho rõ.",explain:"Sai. Ánh sáng chiếu vào mắt gây chói, hại mắt; nên chiếu vào trang vở.",answer:!1},{id:"cn3-den-hoc-12",type:"mc",q:"Vì sao không chạm vào bóng đèn đang sáng?",explain:"Bóng đèn đang sáng có thể rất nóng, chạm vào dễ bị bỏng.",options:["Đèn sẽ to ra","Đèn sẽ đổi màu","Có thể bị bỏng"],answer:2},{id:"cn3-den-hoc-13",type:"multi",q:"Việc làm nào là dùng đèn học an toàn?",explain:"Tay khô, tắt khi học xong là đúng; kéo dây và để nước gần đèn đều nguy hiểm.",options:["Tay khô khi bật đèn","Kéo dây để rút phích","Tắt đèn khi học xong","Để nước gần đèn"],answers:[0,2]},{id:"cn3-den-hoc-14",type:"mc",q:"Học dưới ánh đèn quá tối dễ làm sao?",explain:"Ánh sáng quá yếu làm mắt phải cố nhìn, dễ mỏi và hại mắt.",options:["Viết đẹp hơn","Mắt khỏe hơn","Mỏi, hại mắt"],answer:2},{id:"cn3-den-hoc-15",type:"order",q:"Sắp xếp các bước dùng đèn học.",explain:"Đặt đèn đúng chỗ, cắm điện, bật đèn, chỉnh chụp đèn rồi tắt khi học xong.",items:["Đặt đèn bên tay trái","Người lớn cắm phích điện","Bật công tắc","Chỉnh chụp đèn","Tắt đèn khi học xong"]},{id:"cn3-den-hoc-16",type:"tf",q:"Khi rút phích cắm, cần cầm vào phích, không kéo dây.",explain:"Đúng. Kéo dây dễ làm đứt dây, hở điện.",answer:!0},{id:"cn3-den-hoc-17",type:"mc",q:"Đèn học thường chỉnh được gì cho phù hợp?",explain:"Em chỉnh chụp đèn để ánh sáng chiếu đúng vào trang vở.",options:["Màu của đế đèn","Hướng chiếu sáng","Độ dài của dây"],answer:1},{id:"cn3-den-hoc-18",type:"fill",q:"Bạn viết tay phải nên đặt đèn ở bên tay … .",explain:"Đèn bên trái thì tay phải không che bóng lên vở.",answer:["trái"]}]},{questions:[{id:"cn3-den-hoc-19",type:"mc",q:"Đèn chập chờn và có mùi khét. Lan nên làm gì?",explain:"Đèn có mùi khét là nguy hiểm, Lan báo ngay người lớn.",options:["Báo ngay người lớn","Lắc thật mạnh đèn","Tự tháo bóng đèn"],answer:0},{id:"cn3-den-hoc-20",type:"mc",q:"Nam viết tay trái. Nam nên đặt đèn ở đâu?",explain:"Viết tay trái thì đặt đèn bên phải để tay không che sáng.",options:["Bên trái","Bên phải","Phía sau"],answer:1},{id:"cn3-den-hoc-21",type:"tf",q:"Để cốc nước sát đèn học là an toàn.",explain:"Sai. Nước đổ vào đèn có thể gây điện giật, chập điện.",answer:!1},{id:"cn3-den-hoc-22",type:"multi",q:"Minh muốn đèn học bền. Minh nên làm gì?",explain:"Bật tắt nhẹ, lau khi đã rút điện, để chỗ khô giúp đèn bền.",options:["Bật tắt nhẹ nhàng","Lau bụi khi đã rút điện","Treo đồ lên chụp đèn","Đặt đèn chỗ khô"],answers:[0,1,3]},{id:"cn3-den-hoc-23",type:"match",q:"Nối tình huống với cách xử lí đúng.",explain:"Xử lí đúng giúp em học thoải mái và an toàn.",pairs:[["Đèn quá chói mắt","Chỉnh lại chụp đèn"],["Dây điện bị hở","Báo người lớn"],["Học xong","Tắt đèn"]]},{id:"cn3-den-hoc-24",type:"tf",q:"Tay còn ướt, em không nên bật đèn hay chạm phích điện.",explain:"Đúng. Tay ướt chạm đồ điện dễ bị điện giật.",answer:!0},{id:"cn3-den-hoc-25",type:"mc",q:"Vì sao nên tắt đèn khi không dùng?",explain:"Tắt đèn khi không dùng giúp tiết kiệm điện.",options:["Đèn sáng hơn","Tiết kiệm điện","Phòng mát hơn"],answer:1},{id:"cn3-den-hoc-26",type:"order",q:"Sắp xếp việc làm khi học xong.",explain:"Tắt đèn, nhờ người lớn rút phích rồi cất sách vở.",items:["Tắt công tắc đèn","Nhờ người lớn rút phích","Cất sách vở gọn gàng"]}]}],challenge:{questions:[{id:"cn3-den-hoc-27",type:"mc",q:"Ánh sáng đèn nên chiếu vào đâu khi em viết?",explain:"Ánh sáng chiếu vào trang vở giúp em nhìn rõ chữ.",options:["Vào mắt em","Vào trang vở","Lên trần nhà"],answer:1},{id:"cn3-den-hoc-28",type:"multi",q:"Dấu hiệu nào cho thấy đèn có thể bị hỏng?",explain:"Đèn chập chờn, mùi khét, dây nứt vỏ là dấu hiệu hỏng, cần báo người lớn.",options:["Đèn chập chờn","Có mùi khét","Đèn sáng đều","Dây bị nứt vỏ"],answers:[0,1,3]},{id:"cn3-den-hoc-29",type:"tf",q:"Bóng đèn vừa tắt vẫn có thể còn nóng một lúc.",explain:"Đúng. Bóng đèn cần thời gian để nguội, chưa nên chạm vào.",answer:!0},{id:"cn3-den-hoc-30",type:"mc",q:"Chi viết tay phải mà đặt đèn bên phải. Điều gì xảy ra?",explain:"Đèn bên phải làm tay phải in bóng che chỗ Chi đang viết.",options:["Tay in bóng lên vở","Chữ đẹp hơn hẳn","Đèn bền lâu hơn"],answer:0},{id:"cn3-den-hoc-31",type:"order",q:"Sắp xếp các bộ phận đèn học từ dưới lên trên.",explain:"Đế đèn ở dưới, thân đèn ở giữa, chụp đèn ở trên.",items:["Đế đèn","Thân đèn","Chụp đèn"]},{id:"cn3-den-hoc-32",type:"fill",q:"Học lâu dưới ánh sáng quá yếu sẽ hại … .",explain:"Ánh sáng yếu làm mắt mỏi và hại mắt.",answer:["mắt"]},{id:"cn3-den-hoc-33",type:"tf",q:"Kéo dây điện để rút phích cho nhanh là đúng cách.",explain:"Sai. Phải cầm vào phích để rút, kéo dây dễ làm hỏng dây.",answer:!1}]},summary:["Đèn học chiếu sáng giúp em học bài.","Viết tay phải thì đặt đèn bên trái, ánh sáng chiếu vào trang vở, không chiếu vào mắt.","Tay khô khi dùng đèn, không chạm bóng đèn nóng, học xong thì tắt đèn."]},{id:"cn3-quat-dien",title:"Sử dụng quạt điện",weeks:[8,9],learn:[{title:"Quạt điện giúp gì cho em?",text:"Quạt điện tạo ra gió, làm mát khi trời nóng.",example:"🌀 ➜ 🌬️ gió mát"},{title:"Các bộ phận của quạt điện",text:"Quạt điện thường có cánh quạt, lồng quạt, thân quạt, đế quạt, các nút bấm, dây điện và phích cắm.",example:"🌀 cánh  ·  🛡️ lồng  ·  🔘 nút bấm"},{title:"Dùng quạt an toàn",text:"Không thò tay hay vật vào lồng quạt. Chọn số gió vừa phải, không ngồi quá gần. Quạt kêu lạ, có mùi khét thì tắt và báo người lớn.",example:"🚫✋ lồng quạt  ·  🙋 báo người lớn"}],practice:[{questions:[{id:"cn3-quat-dien-01",type:"mc",q:"Quạt điện dùng để làm gì?",emoji:"🌀",explain:"Quạt điện quay cánh tạo ra gió làm mát.",options:["Nấu chín cơm","Tạo gió mát","Chiếu sáng phòng"],answer:1},{id:"cn3-quat-dien-02",type:"mc",q:"Bộ phận nào quay để tạo ra gió?",explain:"Cánh quạt quay tạo ra gió.",options:["Đế quạt","Cánh quạt","Phích cắm"],answer:1},{id:"cn3-quat-dien-03",type:"mc",q:"Lồng quạt có tác dụng gì?",explain:"Lồng quạt che chắn cánh quạt, giúp tay không chạm vào cánh đang quay.",options:["Phát ra âm thanh","Che chắn cánh quạt","Làm quạt nặng"],answer:1},{id:"cn3-quat-dien-04",type:"tf",q:"Có thể cho ngón tay vào lồng quạt khi quạt đang quay.",explain:"Sai. Cánh quạt đang quay có thể làm đau, đứt tay.",answer:!1},{id:"cn3-quat-dien-05",type:"tf",q:"Các nút trên quạt dùng để bật, tắt và chọn số gió.",explain:"Đúng. Nút bấm giúp bật, tắt quạt và chọn gió mạnh hay nhẹ.",answer:!0},{id:"cn3-quat-dien-06",type:"match",q:"Nối bộ phận quạt với tác dụng.",explain:"Mỗi bộ phận của quạt có một tác dụng riêng.",pairs:[["Cánh quạt","Quay tạo gió"],["Lồng quạt","Che chắn cánh"],["Đế quạt","Giữ quạt đứng vững"],["Nút bấm","Bật, tắt, chỉnh gió"]]},{id:"cn3-quat-dien-07",type:"multi",q:"Đâu là bộ phận của quạt điện?",explain:"Chụp đèn là bộ phận của đèn học, không phải của quạt.",options:["Cánh quạt","Lồng quạt","Chụp đèn","Đế quạt"],answers:[0,1,3]},{id:"cn3-quat-dien-08",type:"fill",q:"Phần quay tạo ra gió gọi là … quạt.",explain:"Cánh quạt quay tạo ra gió.",answer:["cánh"]},{id:"cn3-quat-dien-09",type:"tf",q:"Khi không dùng nữa, em nên tắt quạt.",explain:"Đúng. Tắt quạt khi không dùng để tiết kiệm điện.",answer:!0}]},{questions:[{id:"cn3-quat-dien-10",type:"mc",q:"Vì sao không nên ngồi quá gần quạt?",explain:"Gió thổi mạnh, sát người lâu dễ làm em bị cảm lạnh.",options:["Quạt to hơn","Quạt chạy chậm","Dễ bị cảm lạnh"],answer:2},{id:"cn3-quat-dien-11",type:"multi",q:"Việc làm nào là dùng quạt an toàn?",explain:"Không thò tay vào lồng, bật số vừa phải là dùng quạt an toàn.",options:["Không thò tay vào lồng","Bật số vừa phải","Chọc que vào cánh","Để quạt sát mặt"],answers:[0,1]},{id:"cn3-quat-dien-12",type:"mc",q:"Quạt kêu lạ, có mùi khét. Em nên làm gì?",explain:"Mùi khét là dấu hiệu nguy hiểm, em báo người lớn ngay.",options:["Bật số to hơn","Báo người lớn ngay","Lấy tay giữ cánh"],answer:1},{id:"cn3-quat-dien-13",type:"tf",q:"Trời mát, em vẫn nên bật quạt số to nhất suốt đêm.",explain:"Sai. Bật quạt không cần thiết dễ bị lạnh và tốn điện.",answer:!1},{id:"cn3-quat-dien-14",type:"order",q:"Sắp xếp các bước dùng quạt điện.",explain:"Đặt quạt chắc chắn, cắm điện, chọn số gió và tắt khi không dùng.",items:["Đặt quạt chỗ chắc chắn","Người lớn cắm phích điện","Bấm nút chọn số gió","Tắt quạt khi không dùng"]},{id:"cn3-quat-dien-15",type:"mc",q:"Mái tóc dài của Hà nên tránh xa chỗ nào?",explain:"Tóc dài có thể bị cuốn vào quạt đang quay, rất nguy hiểm.",options:["Cửa sổ lớp học","Bàn học của em","Quạt đang quay"],answer:2},{id:"cn3-quat-dien-16",type:"tf",q:"Muốn di chuyển quạt, cần tắt quạt và rút điện trước.",explain:"Đúng. Tắt quạt và rút điện trước khi di chuyển cho an toàn.",answer:!0},{id:"cn3-quat-dien-17",type:"match",q:"Nối việc làm với kết quả.",explain:"Dùng quạt đúng cách giúp em an toàn và tiết kiệm điện.",pairs:[["Thò tay vào lồng quạt","Dễ bị thương"],["Tắt khi không dùng","Tiết kiệm điện"],["Ngồi sát quạt lâu","Dễ bị cảm lạnh"]]},{id:"cn3-quat-dien-18",type:"fill",q:"Để tiết kiệm điện, em … quạt khi ra khỏi phòng.",explain:"Ra khỏi phòng thì tắt quạt để không tốn điện.",answer:["tắt"]}]},{questions:[{id:"cn3-quat-dien-19",type:"mc",q:"Em nhỏ trong nhà thích nghịch quạt. Em nên làm gì?",explain:"Em nhỏ nghịch quạt dễ bị thương, cần nhắc em tránh xa và báo người lớn.",options:["Cho em thò tay","Nhắc em tránh xa","Mặc kệ em chơi"],answer:1},{id:"cn3-quat-dien-20",type:"mc",q:"Trời hơi nóng, Bình nên chọn số gió nào?",explain:"Trời hơi nóng thì chọn số nhỏ là đủ mát và tiết kiệm điện.",options:["Bật rồi tắt liên tục","Số to nhất","Số nhỏ, vừa phải"],answer:2},{id:"cn3-quat-dien-21",type:"tf",q:"Có thể dùng khăn ướt lau quạt khi quạt đang chạy.",explain:"Sai. Phải tắt quạt, rút điện và chỉ lau bằng khăn khô hoặc hơi ẩm.",answer:!1},{id:"cn3-quat-dien-22",type:"multi",q:"Khi nào cần tắt quạt?",explain:"Tắt quạt khi không dùng hoặc khi quạt có dấu hiệu hỏng.",options:["Ra khỏi phòng","Quạt có mùi khét","Trời đang rất nóng","Quạt kêu lạ"],answers:[0,1,3]},{id:"cn3-quat-dien-23",type:"order",q:"Sắp xếp việc làm khi quạt có tiếng kêu lạ.",explain:"Tắt quạt, báo người lớn để người lớn kiểm tra.",items:["Tắt quạt","Báo người lớn","Người lớn kiểm tra, sửa chữa"]},{id:"cn3-quat-dien-24",type:"match",q:"Nối tình huống với việc nên làm.",explain:"Chọn cách dùng quạt phù hợp và an toàn.",pairs:[["Đi ngủ","Để số nhỏ"],["Quạt bám bụi","Nhờ người lớn lau"],["Dây quạt bị nứt","Ngừng dùng, báo người lớn"]]},{id:"cn3-quat-dien-25",type:"tf",q:"Đặt quạt ở chỗ bằng phẳng, chắc chắn để quạt không bị đổ.",explain:"Đúng. Quạt đổ có thể làm hỏng quạt và gây nguy hiểm.",answer:!0},{id:"cn3-quat-dien-26",type:"mc",q:"Vì sao quạt có lồng bảo vệ?",explain:"Lồng quạt giúp tay và đồ vật không chạm vào cánh đang quay.",options:["Để quạt kêu to hơn","Để quạt nặng thêm","Để tay không chạm cánh"],answer:2}]}],challenge:{questions:[{id:"cn3-quat-dien-27",type:"mc",q:"Quả bóng lăn sát lồng quạt đang quay. An nên làm gì?",explain:"Tắt quạt trước rồi mới lấy bóng để không bị thương.",options:["Thò tay lấy ngay","Tắt quạt rồi lấy","Lấy que chọc"],answer:1},{id:"cn3-quat-dien-28",type:"multi",q:"Dấu hiệu nào cho thấy quạt cần được kiểm tra?",explain:"Kêu lạ, mùi khét, cánh rung mạnh là dấu hiệu quạt có vấn đề.",options:["Kêu lạ","Có mùi khét","Quay êm","Cánh rung mạnh"],answers:[0,1,3]},{id:"cn3-quat-dien-29",type:"tf",q:"Có thể treo quần áo ướt lên quạt điện để phơi.",explain:"Sai. Nước nhỏ vào quạt có thể gây chập điện, điện giật.",answer:!1},{id:"cn3-quat-dien-30",type:"order",q:"Sắp xếp các bộ phận quạt cây từ dưới lên.",explain:"Đế quạt ở dưới, thân quạt ở giữa, lồng và cánh quạt ở trên.",items:["Đế quạt","Thân quạt","Lồng và cánh quạt"]},{id:"cn3-quat-dien-31",type:"fill",q:"Không được cho ngón tay vào … quạt.",explain:"Thò ngón tay vào lồng quạt có thể bị cánh quạt làm đau.",answer:["lồng"]},{id:"cn3-quat-dien-32",type:"mc",q:"Việc nào giúp tiết kiệm điện khi dùng quạt?",explain:"Tắt quạt khi không dùng giúp tiết kiệm điện.",options:["Bật số to nhất","Bật cả ngày","Tắt khi không dùng"],answer:2},{id:"cn3-quat-dien-33",type:"tf",q:"Khi đi ngủ, nên để quạt số nhỏ và không thổi thẳng vào người.",explain:"Đúng. Gió nhẹ, không thổi thẳng giúp em không bị cảm lạnh.",answer:!0}]},summary:["Quạt điện tạo ra gió làm mát.","Quạt có cánh quạt, lồng quạt, thân quạt, đế quạt và các nút bấm.","Không thò tay vào lồng quạt; quạt kêu lạ, có mùi khét thì tắt và báo người lớn."]},{id:"cn3-may-thu-thanh",title:"Sử dụng máy thu thanh",weeks:[10,11],learn:[{title:"Máy thu thanh là gì?",text:"Máy thu thanh còn gọi là đài hay ra-đi-ô. Máy nhận tín hiệu từ đài phát thanh và phát ra âm thanh.",example:"📻 tin tức  ·  🎵 ca nhạc  ·  📖 kể chuyện"},{title:"Các bộ phận chính",text:"Máy thu thanh thường có loa, nút bật tắt, nút chỉnh âm lượng, nút dò kênh và ăng-ten.",example:"🔊 loa  ·  🎚️ âm lượng  ·  📡 ăng-ten"},{title:"Nghe đài đúng cách",text:"Bật máy, chọn kênh, chỉnh âm lượng vừa nghe, nghe xong thì tắt. Không mở quá to.",example:"🔈 vừa nghe  ·  🚫🔊 quá to"}],practice:[{questions:[{id:"cn3-may-thu-thanh-01",type:"mc",q:"Máy thu thanh dùng để làm gì?",emoji:"📻",explain:"Máy thu thanh phát âm thanh như tin tức, ca nhạc.",options:["Xem phim ảnh","Nghe tin tức","Làm mát phòng"],answer:1},{id:"cn3-may-thu-thanh-02",type:"mc",q:"Âm thanh phát ra từ bộ phận nào?",explain:"Loa phát ra âm thanh để em nghe.",options:["Ăng-ten","Cái loa","Nút tắt"],answer:1},{id:"cn3-may-thu-thanh-03",type:"mc",q:"Ăng-ten giúp máy thu thanh làm gì?",emoji:"📡",explain:"Ăng-ten giúp máy thu tín hiệu từ đài phát thanh tốt hơn.",options:["Phát ra ánh sáng","Thu tín hiệu tốt hơn","Làm mát cho máy"],answer:1},{id:"cn3-may-thu-thanh-04",type:"tf",q:"Máy thu thanh còn được gọi là đài hay ra-đi-ô.",explain:"Đúng. Đài, ra-đi-ô là tên gọi khác của máy thu thanh.",answer:!0},{id:"cn3-may-thu-thanh-05",type:"tf",q:"Máy thu thanh có màn hình để xem phim.",explain:"Sai. Máy thu thanh chỉ phát âm thanh, không có hình để xem phim.",answer:!1},{id:"cn3-may-thu-thanh-06",type:"match",q:"Nối bộ phận với tác dụng.",explain:"Mỗi bộ phận của máy thu thanh có một tác dụng.",pairs:[["Loa","Phát ra âm thanh"],["Nút âm lượng","Chỉnh to, nhỏ"],["Nút dò kênh","Chọn chương trình"],["Ăng-ten","Thu tín hiệu"]]},{id:"cn3-may-thu-thanh-07",type:"multi",q:"Chọn những gì em có thể nghe trên máy thu thanh.",explain:"Máy thu thanh phát âm thanh: tin tức, ca nhạc, dự báo thời tiết.",options:["Tin tức","Ca nhạc","Dự báo thời tiết","Mùi thơm"],answers:[0,1,2]},{id:"cn3-may-thu-thanh-08",type:"fill",q:"Âm thanh của đài phát ra từ cái … .",explain:"Loa là bộ phận phát ra âm thanh.",answer:["loa"]},{id:"cn3-may-thu-thanh-09",type:"tf",q:"Nghe đài với âm lượng vừa phải giúp bảo vệ tai.",explain:"Đúng. Âm thanh quá to có thể hại tai.",answer:!0}]},{questions:[{id:"cn3-may-thu-thanh-10",type:"mc",q:"Vì sao không nên mở đài quá to?",explain:"Âm thanh quá to hại tai và làm phiền mọi người.",options:["Đài sẽ bền hơn","Nghe sẽ hay hơn","Hại tai mọi người"],answer:2},{id:"cn3-may-thu-thanh-11",type:"order",q:"Sắp xếp các bước nghe đài.",explain:"Bật máy, chọn kênh, chỉnh âm lượng và tắt khi nghe xong.",items:["Bật máy thu thanh","Chọn kênh muốn nghe","Chỉnh âm lượng vừa nghe","Tắt máy khi nghe xong"]},{id:"cn3-may-thu-thanh-12",type:"tf",q:"Muốn nghe kênh khác, em dùng nút dò kênh.",explain:"Đúng. Nút dò kênh giúp chọn chương trình khác.",answer:!0},{id:"cn3-may-thu-thanh-13",type:"mc",q:"Tiếng đài bị rè, không rõ. Em có thể làm gì?",explain:"Chỉnh ăng-ten giúp máy thu tín hiệu rõ hơn.",options:["Đập mạnh vào đài","Lắc đài thật mạnh","Chỉnh lại ăng-ten"],answer:2},{id:"cn3-may-thu-thanh-14",type:"multi",q:"Việc nào là dùng đài đúng cách?",explain:"Mở vừa phải và tắt khi nghe xong là dùng đúng cách.",options:["Mở âm lượng vừa phải","Tắt khi nghe xong","Để đài nơi ẩm ướt","Vặn nút thật mạnh"],answers:[0,1]},{id:"cn3-may-thu-thanh-15",type:"mc",q:"Đài chạy pin lâu không dùng, nên làm gì?",emoji:"🔋",explain:"Tháo pin ra để pin không chảy nước làm hỏng đài.",options:["Tháo pin ra","Ngâm vào nước","Để ngoài nắng"],answer:0},{id:"cn3-may-thu-thanh-16",type:"tf",q:"Có thể mở đài thật to lúc mọi người đang ngủ trưa.",explain:"Sai. Mở đài to lúc mọi người ngủ là làm phiền người khác.",answer:!1},{id:"cn3-may-thu-thanh-17",type:"match",q:"Nối chương trình với điều em biết thêm.",explain:"Mỗi chương trình cho em biết thêm điều khác nhau.",pairs:[["Dự báo thời tiết","Trời nắng hay mưa"],["Bản tin","Sự việc mới xảy ra"],["Ca nhạc","Bài hát hay"]]},{id:"cn3-may-thu-thanh-18",type:"fill",q:"Nút chỉnh to, nhỏ gọi là nút âm … .",explain:"Nút âm lượng chỉnh tiếng to hay nhỏ.",answer:["lượng"]}]},{questions:[{id:"cn3-may-thu-thanh-19",type:"mc",q:"Ông muốn nghe tin buổi sáng. Em giúp ông thế nào?",explain:"Em bật đài và chọn kênh tin tức cho ông nghe.",options:["Cất đài lên nóc tủ","Rút pin của đài","Bật đài, chọn kênh"],answer:2},{id:"cn3-may-thu-thanh-20",type:"mc",q:"Em bé đang ngủ, Minh muốn nghe nhạc. Minh nên làm gì?",explain:"Vặn nhỏ để không làm em bé thức giấc.",options:["Mở thật to lên","Mở to dần lên","Vặn nhỏ âm lượng"],answer:2},{id:"cn3-may-thu-thanh-21",type:"tf",q:"Lau đài bằng khăn ướt sũng nước là tốt.",explain:"Sai. Nước vào đài có thể làm hỏng đài, gây chập điện.",answer:!1},{id:"cn3-may-thu-thanh-22",type:"multi",q:"Nghe dự báo trời sắp mưa, em nên làm gì?",explain:"Biết trời sắp mưa, em mang áo mưa và đem quần áo vào nhà.",options:["Mang áo mưa","Đem quần áo vào","Đi tắm sông","Phơi chăn ra sân"],answers:[0,1]},{id:"cn3-may-thu-thanh-23",type:"order",q:"Sắp xếp việc tìm kênh ca nhạc thiếu nhi.",explain:"Bật đài, dò kênh, dừng ở kênh thiếu nhi rồi chỉnh âm lượng.",items:["Bật đài","Xoay nút dò kênh","Nghe thấy kênh thiếu nhi thì dừng","Chỉnh âm lượng vừa nghe"]},{id:"cn3-may-thu-thanh-24",type:"tf",q:"Đài cắm điện có dây hỏng thì không được dùng, phải báo người lớn.",explain:"Đúng. Dây điện hỏng có thể gây điện giật.",answer:!0},{id:"cn3-may-thu-thanh-25",type:"match",q:"Nối tình huống với cách xử lí.",explain:"Xử lí đúng giúp nghe đài rõ và an toàn.",pairs:[["Tiếng quá to","Vặn nhỏ âm lượng"],["Tiếng rè","Chỉnh ăng-ten"],["Đài hết pin","Nhờ người lớn thay pin"]]},{id:"cn3-may-thu-thanh-26",type:"mc",q:"Máy thu thanh khác máy thu hình ở điểm nào?",explain:"Máy thu thanh chỉ phát âm thanh; máy thu hình có cả hình và tiếng.",options:["Có cả hình ảnh","Chỉ phát âm thanh","Không có cái loa"],answer:1}]}],challenge:{questions:[{id:"cn3-may-thu-thanh-27",type:"mc",q:"Bản tin báo bão sắp đến. Gia đình nên làm gì?",explain:"Nghe tin bão, gia đình chuẩn bị phòng tránh cho an toàn.",options:["Đi tắm biển","Chuẩn bị phòng tránh","Ra đồng thả diều"],answer:1},{id:"cn3-may-thu-thanh-28",type:"multi",q:"Bộ phận nào có ở máy thu thanh?",explain:"Máy thu thanh có loa, nút dò kênh, nút âm lượng.",options:["Loa","Nút dò kênh","Cánh quạt","Nút âm lượng","Chụp đèn"],answers:[0,1,3]},{id:"cn3-may-thu-thanh-29",type:"tf",q:"Máy thu thanh nhận tín hiệu từ đài phát thanh rồi phát ra âm thanh.",explain:"Đúng. Đài phát thanh phát đi, máy thu thanh nhận và phát ra loa.",answer:!0},{id:"cn3-may-thu-thanh-30",type:"order",q:"Sắp xếp đường đi của chương trình đến tai em.",explain:"Đài phát đi, máy thu nhận, loa phát ra, em nghe được.",items:["Đài phát thanh phát đi","Máy thu thanh nhận tín hiệu","Loa phát ra âm thanh","Em nghe được"]},{id:"cn3-may-thu-thanh-31",type:"fill",q:"Đài … nói Việt Nam là đài phát thanh quốc gia.",explain:"Đài Tiếng nói Việt Nam là đài phát thanh quốc gia.",answer:["Tiếng"]},{id:"cn3-may-thu-thanh-32",type:"mc",q:"Nghe đài bằng tai nghe, nên để âm lượng thế nào?",explain:"Đeo tai nghe mà mở to dễ hại tai, nên để vừa phải.",options:["Thật to","To nhất","Vừa phải"],answer:2},{id:"cn3-may-thu-thanh-33",type:"tf",q:"Có thể mang đài vào dùng khi đang tắm dưới vòi nước.",explain:"Sai. Nước làm hỏng đài và có thể gây nguy hiểm.",answer:!1}]},summary:["Máy thu thanh (đài, ra-đi-ô) nhận tín hiệu từ đài phát thanh và phát ra âm thanh.","Máy có loa, nút bật tắt, nút âm lượng, nút dò kênh và ăng-ten.","Nghe đài với âm lượng vừa phải, nghe xong thì tắt."]},{id:"cn3-may-thu-hinh",title:"Sử dụng máy thu hình",weeks:[12,13],learn:[{title:"Máy thu hình là gì?",text:"Máy thu hình còn gọi là ti vi. Ti vi nhận tín hiệu từ đài truyền hình, cho em xem hình ảnh và nghe âm thanh.",example:"📺 hình ảnh + 🔊 âm thanh"},{title:"Các bộ phận chính",text:"Ti vi có màn hình, loa và điều khiển từ xa để bật tắt, chọn kênh, chỉnh âm lượng.",example:"🖥️ màn hình  ·  🔊 loa  ·  🎛️ điều khiển"},{title:"Xem ti vi đúng cách",text:"Ngồi ngay ngắn, cách xa màn hình, không xem quá lâu, mở âm lượng vừa phải, chọn chương trình phù hợp.",example:"🪑 ngồi xa  ·  ⏱️ xem vừa đủ"}],practice:[{questions:[{id:"cn3-may-thu-hinh-01",type:"mc",q:"Máy thu hình còn được gọi là gì?",emoji:"📺",explain:"Máy thu hình còn gọi là ti vi.",options:["Ti vi","Máy giặt","Quạt điện"],answer:0},{id:"cn3-may-thu-hinh-02",type:"mc",q:"Hình ảnh hiện ra ở bộ phận nào?",explain:"Hình ảnh hiện ra trên màn hình ti vi.",options:["Màn hình","Điều khiển","Cái loa"],answer:0},{id:"cn3-may-thu-hinh-03",type:"mc",q:"Dùng gì để đổi kênh khi ngồi xa ti vi?",emoji:"🎛️",explain:"Điều khiển từ xa giúp đổi kênh mà không cần đến gần ti vi.",options:["Bút chì màu","Chiếc thìa nhỏ","Điều khiển"],answer:2},{id:"cn3-may-thu-hinh-04",type:"tf",q:"Máy thu hình cho em vừa xem hình vừa nghe tiếng.",explain:"Đúng. Ti vi có màn hình để xem và loa để nghe.",answer:!0},{id:"cn3-may-thu-hinh-05",type:"tf",q:"Xem ti vi càng gần màn hình càng tốt cho mắt.",explain:"Sai. Ngồi quá gần màn hình dễ làm mỏi mắt, hại mắt.",answer:!1},{id:"cn3-may-thu-hinh-06",type:"match",q:"Nối bộ phận ti vi với tác dụng.",explain:"Mỗi bộ phận của ti vi có một tác dụng.",pairs:[["Màn hình","Hiện hình ảnh"],["Loa","Phát âm thanh"],["Điều khiển","Bật, tắt, đổi kênh"]]},{id:"cn3-may-thu-hinh-07",type:"multi",q:"Chương trình nào có thể xem trên ti vi?",explain:"Ti vi có phim hoạt hình, thời sự, dự báo thời tiết; mùi thì không xem được.",options:["Phim hoạt hình","Thời sự","Dự báo thời tiết","Mùi thức ăn"],answers:[0,1,2]},{id:"cn3-may-thu-hinh-08",type:"fill",q:"Hình ảnh trên ti vi hiện ra ở màn … .",explain:"Màn hình là nơi hiện hình ảnh.",answer:["hình"]},{id:"cn3-may-thu-hinh-09",type:"tf",q:"Xem ti vi xong, em nên tắt ti vi.",explain:"Đúng. Tắt ti vi khi không xem để tiết kiệm điện.",answer:!0}]},{questions:[{id:"cn3-may-thu-hinh-10",type:"mc",q:"Ngồi xem ti vi thế nào là đúng?",explain:"Ngồi ngay ngắn, cách xa màn hình giúp bảo vệ mắt.",options:["Nằm sát màn hình","Ngồi xa, ngay ngắn","Ngồi lệch một bên"],answer:1},{id:"cn3-may-thu-hinh-11",type:"tf",q:"Xem ti vi quá lâu dễ làm mỏi mắt.",explain:"Đúng. Nên xem vừa đủ và cho mắt nghỉ.",answer:!0},{id:"cn3-may-thu-hinh-12",type:"multi",q:"Việc nào giúp bảo vệ mắt khi xem ti vi?",explain:"Ngồi xa và xem vừa đủ giúp mắt không mỏi.",options:["Ngồi cách xa màn hình","Xem vừa đủ thời gian","Xem trong phòng tối om","Dụi mắt liên tục"],answers:[0,1]},{id:"cn3-may-thu-hinh-13",type:"mc",q:"Vì sao nên chọn chương trình hợp lứa tuổi?",explain:"Chương trình hợp lứa tuổi dễ hiểu và bổ ích cho em.",options:["Bổ ích cho em","Ti vi bền hơn","Đỡ phải tắt"],answer:0},{id:"cn3-may-thu-hinh-14",type:"order",q:"Sắp xếp các bước xem ti vi.",explain:"Bật ti vi, chọn kênh, chỉnh âm lượng và tắt khi xem xong.",items:["Bật ti vi bằng điều khiển","Chọn kênh phù hợp","Chỉnh âm lượng vừa nghe","Tắt ti vi khi xem xong"]},{id:"cn3-may-thu-hinh-15",type:"tf",q:"Có thể dùng tay ướt để bật ti vi.",explain:"Sai. Tay ướt chạm đồ điện dễ bị điện giật.",answer:!1},{id:"cn3-may-thu-hinh-16",type:"mc",q:"Màn hình ti vi bám bụi. Em nên làm gì?",explain:"Người lớn sẽ rút điện và lau bằng khăn mềm, khô.",options:["Nhờ người lớn lau","Dội nước lên màn","Dùng bút cạo bụi"],answer:0},{id:"cn3-may-thu-hinh-17",type:"match",q:"Nối chương trình với điều em xem được.",explain:"Mỗi chương trình ti vi có nội dung riêng.",pairs:[["Thời sự","Tin tức trong ngày"],["Phim hoạt hình","Câu chuyện vui"],["Dự báo thời tiết","Nắng, mưa ngày mai"]]},{id:"cn3-may-thu-hinh-18",type:"fill",q:"Em đổi kênh ti vi bằng cái điều … từ xa.",explain:"Điều khiển từ xa giúp bật tắt, đổi kênh ti vi.",answer:["khiển"]}]},{questions:[{id:"cn3-may-thu-hinh-19",type:"mc",q:"Đến giờ đi ngủ mà phim chưa hết. An nên làm gì?",explain:"Ngủ đúng giờ giúp An khỏe; An có thể xem tiếp vào lúc khác.",options:["Bật to hơn","Xem tiếp đến khuya","Tắt ti vi đi ngủ"],answer:2},{id:"cn3-may-thu-hinh-20",type:"mc",q:"Bà đang nghỉ, em muốn xem ti vi. Em nên làm gì?",explain:"Mở nhỏ để không làm phiền bà nghỉ ngơi.",options:["Mở âm lượng nhỏ","Đập điều khiển","Mở thật to"],answer:0},{id:"cn3-may-thu-hinh-21",type:"tf",q:"Vừa ăn cơm vừa mải xem ti vi là thói quen tốt.",explain:"Sai. Mải xem ti vi khi ăn làm em ăn uống không tập trung.",answer:!1},{id:"cn3-may-thu-hinh-22",type:"multi",q:"Khi ti vi có mùi khét, em nên làm gì?",explain:"Tắt ti vi và báo người lớn; không tự mở, không đổ nước.",options:["Tắt ti vi","Báo người lớn","Tự mở vỏ ti vi","Đổ nước vào"],answers:[0,1]},{id:"cn3-may-thu-hinh-23",type:"match",q:"Nối tình huống với việc nên làm.",explain:"Xử lí đúng giúp em xem ti vi khỏe mạnh, an toàn.",pairs:[["Mỏi mắt","Nghỉ, nhìn ra xa"],["Tiếng quá to","Vặn nhỏ âm lượng"],["Xem xong","Tắt ti vi"]]},{id:"cn3-may-thu-hinh-24",type:"order",q:"Sắp xếp việc làm khi xem ti vi xong.",explain:"Tắt ti vi, cất điều khiển rồi làm việc khác.",items:["Tắt ti vi","Cất điều khiển đúng chỗ","Đi làm việc khác"]},{id:"cn3-may-thu-hinh-25",type:"tf",q:"Bạn nhỏ không nên tự leo lên kệ để chỉnh ti vi.",explain:"Đúng. Leo trèo dễ ngã, làm đổ ti vi; hãy nhờ người lớn.",answer:!0},{id:"cn3-may-thu-hinh-26",type:"mc",q:"Muốn xem dự báo thời tiết, em dùng gì?",explain:"Ti vi có chương trình dự báo thời tiết.",options:["Máy giặt","Tủ lạnh","Ti vi"],answer:2}]}],challenge:{questions:[{id:"cn3-may-thu-hinh-27",type:"mc",q:"Máy thu hình nhận tín hiệu từ đâu?",explain:"Ti vi nhận tín hiệu từ đài truyền hình.",options:["Bóng đèn bàn","Đài truyền hình","Máy giặt quần áo"],answer:1},{id:"cn3-may-thu-hinh-28",type:"multi",q:"Đâu là thói quen xem ti vi tốt?",explain:"Xem vừa đủ, ngồi xa, chọn chương trình bổ ích là thói quen tốt.",options:["Xem vừa đủ giờ","Ngồi xa màn hình","Vừa ăn vừa xem","Chọn chương trình bổ ích"],answers:[0,1,3]},{id:"cn3-may-thu-hinh-29",type:"tf",q:"Máy thu hình có cả màn hình và loa.",explain:"Đúng. Màn hình hiện hình, loa phát tiếng.",answer:!0},{id:"cn3-may-thu-hinh-30",type:"order",q:"Sắp xếp đường đi của hình ảnh đến mắt em.",explain:"Đài phát đi, ti vi nhận, màn hình hiện hình, em xem được.",items:["Đài truyền hình phát đi","Ti vi nhận tín hiệu","Màn hình hiện hình ảnh","Em xem được"]},{id:"cn3-may-thu-hinh-31",type:"fill",q:"Đài … hình Việt Nam là đài truyền hình quốc gia.",explain:"Đài Truyền hình Việt Nam là đài truyền hình quốc gia.",answer:["Truyền"]},{id:"cn3-may-thu-hinh-32",type:"mc",q:"Máy thu hình khác máy thu thanh ở chỗ nào?",explain:"Cả hai đều có loa; chỉ máy thu hình có màn hình để xem.",options:["Có cái loa","Cần dùng điện","Có màn hình"],answer:2},{id:"cn3-may-thu-hinh-33",type:"tf",q:"Ngồi xem ti vi nhiều giờ liền không ảnh hưởng gì đến sức khỏe.",explain:"Sai. Xem quá lâu làm mỏi mắt và ít vận động.",answer:!1}]},summary:["Máy thu hình (ti vi) cho em xem hình ảnh và nghe âm thanh.","Ti vi có màn hình, loa và điều khiển từ xa.","Ngồi xa màn hình, xem vừa đủ, mở âm lượng vừa phải, xem xong thì tắt."]},{id:"cn3-an-toan-cong-nghe",title:"An toàn với môi trường công nghệ trong gia đình",weeks:[14,16],learn:[{title:"Những nguy hiểm trong nhà",text:"Đồ dùng trong nhà có thể gây nguy hiểm: điện giật, bỏng, đứt tay, cháy.",example:"⚡ ổ điện  ·  🔥 bàn là, ấm sôi  ·  🔪 dao, kéo"},{title:"Phòng tránh nguy hiểm",text:"Không chạm vào ổ điện, dây điện hở. Không dùng đồ điện khi tay ướt. Tránh xa đồ đang nóng. Dùng dao, kéo cần người lớn giúp.",example:"🚫⚡  ·  🖐️ tay khô  ·  🙋 nhờ người lớn"},{title:"Khi có sự cố",text:"Thấy khói, mùi khét, tia lửa: tránh xa và gọi người lớn ngay. Có cháy thì gọi 114.",example:"🔥 ➜ 🙋 ➜ ☎️ 114"}],practice:[{questions:[{id:"cn3-an-toan-cong-nghe-01",type:"mc",q:"Chỗ nào trong nhà dễ gây điện giật?",emoji:"⚡",explain:"Ổ cắm có điện, chạm vào có thể bị điện giật.",options:["Cái gối","Quyển sách","Ổ cắm điện"],answer:2},{id:"cn3-an-toan-cong-nghe-02",type:"mc",q:"Đồ vật nào dễ gây bỏng?",emoji:"🔥",explain:"Nước vừa sôi rất nóng, chạm vào dễ bị bỏng.",options:["Quyển vở mới","Chiếc gối bông","Ấm nước vừa sôi"],answer:2},{id:"cn3-an-toan-cong-nghe-03",type:"tf",q:"Cho ngón tay hoặc vật kim loại vào ổ điện rất nguy hiểm.",explain:"Đúng. Làm vậy có thể bị điện giật.",answer:!0},{id:"cn3-an-toan-cong-nghe-04",type:"tf",q:"Tay ướt vẫn có thể cắm phích điện.",explain:"Sai. Tay ướt chạm điện dễ bị điện giật.",answer:!1},{id:"cn3-an-toan-cong-nghe-05",type:"match",q:"Nối đồ vật với nguy hiểm có thể gặp.",explain:"Biết nguy hiểm của từng đồ vật giúp em phòng tránh.",pairs:[["Ổ điện","Điện giật"],["Bàn là nóng","Bỏng"],["Dao sắc","Đứt tay"]]},{id:"cn3-an-toan-cong-nghe-06",type:"multi",q:"Đồ dùng nào có thể gây bỏng?",explain:"Nồi cơm, ấm siêu tốc, bàn là khi dùng đều nóng, dễ gây bỏng.",options:["Nồi cơm đang nấu","Ấm siêu tốc","Bàn là đang dùng","Gấu bông"],answers:[0,1,2]},{id:"cn3-an-toan-cong-nghe-07",type:"fill",q:"Chạm vào dây điện bị hở có thể bị điện … .",explain:"Dây điện hở rất nguy hiểm, có thể gây điện giật.",answer:["giật"]},{id:"cn3-an-toan-cong-nghe-08",type:"mc",q:"Thấy dây điện bị hở, em làm gì?",explain:"Không chạm vào dây hở, báo ngay người lớn.",options:["Cầm lên xem","Lấy kéo cắt","Báo người lớn"],answer:2},{id:"cn3-an-toan-cong-nghe-09",type:"tf",q:"Dùng dao, kéo sắc cần có người lớn giúp đỡ.",explain:"Đúng. Dao kéo sắc dễ làm đứt tay.",answer:!0}]},{questions:[{id:"cn3-an-toan-cong-nghe-10",type:"mc",q:"Vì sao không chơi đùa gần bếp đang đun?",explain:"Bếp đang đun rất nóng, chơi gần dễ bị bỏng.",options:["Bếp sẽ tắt","Dễ bị bỏng","Cơm ngon hơn"],answer:1},{id:"cn3-an-toan-cong-nghe-11",type:"multi",q:"Việc làm nào giúp em an toàn với điện?",explain:"Không chạm ổ điện và lau khô tay giúp em an toàn.",options:["Không chạm ổ điện","Lau khô tay trước","Chọc que vào ổ","Kéo dây rút phích"],answers:[0,1]},{id:"cn3-an-toan-cong-nghe-12",type:"tf",q:"Thả diều gần đường dây điện là nguy hiểm.",explain:"Đúng. Diều vướng dây điện có thể gây điện giật.",answer:!0},{id:"cn3-an-toan-cong-nghe-13",type:"mc",q:"Nồi cơm điện đang sôi, hơi bốc lên. Em nên làm gì?",explain:"Hơi nước nóng có thể gây bỏng, em đứng tránh xa.",options:["Ghé mặt vào xem","Đứng tránh xa","Mở nắp ra"],answer:1},{id:"cn3-an-toan-cong-nghe-14",type:"order",q:"Sắp xếp việc làm khi thấy đồ điện bốc khói.",explain:"Tránh xa, gọi người lớn để người lớn ngắt điện và xử lí.",items:["Tránh xa đồ điện đó","Gọi người lớn ngay","Người lớn ngắt điện, xử lí"]},{id:"cn3-an-toan-cong-nghe-15",type:"tf",q:"Ổ cắm điện có thể dùng làm đồ chơi.",explain:"Sai. Ổ cắm có điện, không bao giờ được nghịch.",answer:!1},{id:"cn3-an-toan-cong-nghe-16",type:"match",q:"Nối việc nên làm với nguy hiểm tránh được.",explain:"Mỗi việc làm đúng giúp tránh một nguy hiểm.",pairs:[["Không chạm ổ điện","Điện giật"],["Tránh xa ấm sôi","Bỏng"],["Cất kéo đúng chỗ","Đứt tay"]]},{id:"cn3-an-toan-cong-nghe-17",type:"mc",q:"Đồ điện bị rơi vào nước, em nên làm gì?",explain:"Không chạm vào, gọi người lớn ngắt điện.",options:["Nhặt lên ngay","Gọi người lớn","Thò tay vớt ra"],answer:1},{id:"cn3-an-toan-cong-nghe-18",type:"number",q:"Khi có cháy, cần gọi số điện thoại nào?",emoji:"🚒",explain:"Số 114 là số gọi cứu hỏa, cứu nạn cứu hộ.",answer:114}]},{questions:[{id:"cn3-an-toan-cong-nghe-19",type:"mc",q:"Em nhỏ cầm kéo sắc chạy chơi. Em nên làm gì?",explain:"Báo người lớn để lấy kéo cất đi; đuổi giật dễ làm cả hai bị thương.",options:["Báo người lớn ngay","Đuổi theo giật kéo","Mặc kệ em chơi"],answer:0},{id:"cn3-an-toan-cong-nghe-20",type:"mc",q:"Vì sao không dùng đồ điện khi tay ướt?",explain:"Nước dẫn điện, tay ướt dễ bị điện giật.",options:["Dễ bị điện giật","Đồ điện mau bẩn","Tay sẽ khô ngay"],answer:0},{id:"cn3-an-toan-cong-nghe-21",type:"tf",q:"Thấy bạn bị điện giật, em lấy tay kéo bạn ra ngay.",explain:"Sai. Chạm vào người bị điện giật em cũng có thể bị giật; hãy gọi người lớn ngắt điện.",answer:!1},{id:"cn3-an-toan-cong-nghe-22",type:"multi",q:"Thấy có cháy trong nhà, em nên làm gì?",explain:"Báo người lớn, ra chỗ an toàn, gọi 114; không trốn trong nhà.",options:["Hô to gọi người lớn","Chạy ra chỗ an toàn","Trốn vào gầm giường","Gọi 114 nếu cần"],answers:[0,1,3]},{id:"cn3-an-toan-cong-nghe-23",type:"order",q:"Sắp xếp các bước rút phích điện an toàn.",explain:"Tắt thiết bị, tay khô cầm vào phích rồi rút ra.",items:["Tắt công tắc thiết bị","Tay khô cầm vào phích","Rút phích ra khỏi ổ"]},{id:"cn3-an-toan-cong-nghe-24",type:"match",q:"Nối tình huống với cách xử lí đúng.",explain:"Xử lí đúng giúp cả nhà an toàn.",pairs:[["Ổ điện cháy đen","Báo người lớn"],["Ấm nước đang sôi","Đứng tránh xa"],["Dao để mép bàn","Nhờ cất chỗ an toàn"]]},{id:"cn3-an-toan-cong-nghe-25",type:"tf",q:"Đồ điện để gần nước dễ gây nguy hiểm.",explain:"Đúng. Nước vào đồ điện có thể gây chập điện, điện giật.",answer:!0},{id:"cn3-an-toan-cong-nghe-26",type:"mc",q:"Đâu là chỗ an toàn để em ngồi học?",explain:"Chỗ học nên xa bếp và ổ điện cho an toàn.",options:["Xa bếp và ổ điện","Cạnh bếp đang đun","Sát ổ điện bị hở"],answer:0}]}],challenge:{questions:[{id:"cn3-an-toan-cong-nghe-27",type:"mc",q:"Bình thấy mùi khét từ ổ cắm. Bình nên làm gì trước?",explain:"Mùi khét ở ổ cắm rất nguy hiểm, Bình báo người lớn ngay.",options:["Rút thử phích ra","Báo người lớn ngay","Đổ nước vào ổ"],answer:1},{id:"cn3-an-toan-cong-nghe-28",type:"multi",q:"Đâu là hành động nguy hiểm?",explain:"Chọc ổ điện, thả diều gần dây điện, sờ bàn là nóng đều nguy hiểm.",options:["Chọc que vào ổ điện","Thả diều gần dây điện","Tắt đèn khi ra khỏi phòng","Sờ bàn là đang nóng"],answers:[0,1,3]},{id:"cn3-an-toan-cong-nghe-29",type:"tf",q:"Khi có người bị điện giật, cần người lớn ngắt điện trước khi giúp.",explain:"Đúng. Ngắt điện trước để người cứu không bị giật.",answer:!0},{id:"cn3-an-toan-cong-nghe-30",type:"fill",q:"Không được chạm vào ổ … bằng tay ướt.",explain:"Tay ướt chạm ổ điện rất dễ bị điện giật.",answer:["điện"]},{id:"cn3-an-toan-cong-nghe-14",type:"order",q:"Sắp xếp việc làm khi thấy đồ điện bốc khói.",explain:"Tránh xa, gọi người lớn để người lớn ngắt điện và xử lí.",items:["Tránh xa đồ điện đó","Gọi người lớn ngay","Người lớn ngắt điện, xử lí"]},{id:"cn3-an-toan-cong-nghe-31",type:"match",q:"Nối đồ dùng với cách dùng an toàn.",explain:"Mỗi đồ dùng có cách dùng an toàn riêng.",pairs:[["Bàn là","Để người lớn dùng"],["Kéo","Đưa phần chuôi cho bạn"],["Quạt","Không thò tay vào lồng"]]},{id:"cn3-an-toan-cong-nghe-32",type:"mc",q:"Vì sao phải để ổ cắm xa tầm tay em bé?",explain:"Em bé chưa biết nguy hiểm, dễ nghịch ổ điện và bị điện giật.",options:["Để dây dài hơn","Để ổ điện đẹp hơn","Để em bé an toàn"],answer:2}]},summary:["Trong nhà có thể gặp nguy hiểm: điện giật, bỏng, đứt tay, cháy.","Không chạm ổ điện, dây hở; không dùng đồ điện khi tay ướt; tránh xa đồ nóng.","Thấy khói, mùi khét, tia lửa thì tránh xa và gọi người lớn; có cháy gọi 114."]}]},{id:"lam-do-dung-hoc-tap",title:"Làm đồ dùng học tập",lessons:[{id:"cn3-vat-lieu-dung-cu",title:"Vật liệu và dụng cụ làm thủ công",weeks:[17,18],learn:[{title:"Vật liệu làm thủ công",text:"Vật liệu là thứ em dùng để làm nên sản phẩm, như giấy màu, bìa cứng, vỏ hộp, ống hút, que kem.",example:"📄 giấy màu  ·  📦 bìa cứng  ·  🥤 ống hút"},{title:"Dụng cụ làm thủ công",text:"Dụng cụ là đồ em dùng để đo, kẻ, cắt, dán, như thước kẻ, bút chì, kéo, hồ dán.",example:"📏 thước  ·  ✏️ bút chì  ·  ✂️ kéo  ·  🧴 hồ dán"},{title:"Làm việc an toàn, gọn gàng",text:"Dùng kéo cẩn thận, đưa cán kéo về phía bạn khi đưa kéo. Làm xong thì cất dụng cụ và thu dọn giấy vụn.",example:"✂️ cầm cán  ·  🧹 thu dọn  ·  🧼 rửa tay"}],practice:[{questions:[{id:"cn3-vat-lieu-dung-cu-01",type:"mc",q:"Đồ dùng nào là dụng cụ để cắt giấy?",emoji:"✂️",explain:"Kéo là dụng cụ dùng để cắt giấy, cắt bìa.",options:["Hồ dán","Giấy màu","Cái kéo","Bút chì"],answer:2},{id:"cn3-vat-lieu-dung-cu-02",type:"mc",q:"Em dùng gì để kẻ đường thẳng lên giấy?",emoji:"📏",explain:"Thước kẻ giúp em kẻ đường thẳng cho đẹp.",options:["Cái kéo","Thước kẻ","Hồ dán","Ống hút"],answer:1},{id:"cn3-vat-lieu-dung-cu-03",type:"tf",q:"Giấy màu là một vật liệu làm thủ công.",emoji:"📄",explain:"Đúng. Giấy màu là vật liệu để làm nên sản phẩm.",answer:!0},{id:"cn3-vat-lieu-dung-cu-04",type:"tf",q:"Cái kéo là một vật liệu làm thủ công.",emoji:"✂️",explain:"Sai. Kéo là dụng cụ để cắt, không phải vật liệu.",answer:!1},{id:"cn3-vat-lieu-dung-cu-05",type:"match",q:"Nối dụng cụ với việc em dùng nó để làm.",explain:"Thước để kẻ, kéo để cắt, hồ để dán.",pairs:[["Thước kẻ","Kẻ đường thẳng"],["Cái kéo","Cắt giấy"],["Hồ dán","Dán giấy"]]},{id:"cn3-vat-lieu-dung-cu-06",type:"mc",q:"Đồ dùng nào giúp dán hai tờ giấy với nhau?",emoji:"🧴",explain:"Hồ dán giúp các mảnh giấy dính vào nhau.",options:["Bút chì","Thước kẻ","Hồ dán","Cục tẩy"],answer:2},{id:"cn3-vat-lieu-dung-cu-07",type:"fill",q:"Em dùng bút … để vẽ, kẻ nhẹ trước khi cắt.",emoji:"✏️",explain:"Bút chì kẻ nhẹ, sai thì tẩy được.",answer:["chì"]},{id:"cn3-vat-lieu-dung-cu-08",type:"multi",q:"Đâu là vật liệu làm thủ công?",explain:"Bìa cứng, giấy màu là vật liệu; kéo, thước là dụng cụ.",options:["Bìa cứng","Cái kéo","Giấy màu","Thước kẻ"],answers:[0,2]},{id:"cn3-vat-lieu-dung-cu-09",type:"mc",q:"Vỏ hộp giấy sạch có thể dùng làm gì?",emoji:"📦",explain:"Vỏ hộp sạch là vật liệu tái chế để làm đồ dùng, đồ chơi.",options:["Dụng cụ để đo","Vật liệu thủ công","Dụng cụ để cắt","Đồ ăn"],answer:1}]},{questions:[{id:"cn3-vat-lieu-dung-cu-10",type:"mc",q:"Khi đưa kéo cho bạn, em cầm kéo thế nào?",emoji:"✂️",explain:"Em cầm phần lưỡi đã khép, đưa cán kéo về phía bạn để bạn không bị đứt tay.",options:["Đưa cán về phía bạn","Chĩa mũi về bạn","Ném kéo cho bạn","Mở rộng lưỡi kéo"],answer:0},{id:"cn3-vat-lieu-dung-cu-11",type:"tf",q:"Vừa cầm kéo vừa chạy nhảy trong lớp là nguy hiểm.",emoji:"⚠️",explain:"Đúng. Ngã khi cầm kéo có thể làm em hoặc bạn bị thương.",answer:!0},{id:"cn3-vat-lieu-dung-cu-12",type:"tf",q:"Hồ dán có thể đưa lên miệng nếm thử.",emoji:"🧴",explain:"Sai. Hồ dán, keo dán không được đưa lên miệng.",answer:!1},{id:"cn3-vat-lieu-dung-cu-13",type:"mc",q:"Vì sao nên kẻ bằng bút chì trước khi cắt?",emoji:"✏️",explain:"Kẻ trước giúp cắt thẳng, đúng kích thước; nét chì sai có thể tẩy.",options:["Để giấy thơm hơn","Để cắt đúng, thẳng","Để giấy cứng hơn","Để khỏi cần kéo"],answer:1},{id:"cn3-vat-lieu-dung-cu-14",type:"match",q:"Nối vật liệu với đặc điểm của nó.",explain:"Bìa cứng dày và chắc, giấy màu mỏng dễ gấp, ống hút rỗng ở giữa.",pairs:[["Bìa cứng","Dày, chắc"],["Giấy màu","Mỏng, dễ gấp"],["Ống hút","Rỗng ở giữa"]]},{id:"cn3-vat-lieu-dung-cu-15",type:"multi",q:"Việc nào giúp em làm thủ công an toàn?",explain:"Ngồi ngay ngắn, dùng kéo đầu tròn và cất kéo sau khi dùng giúp em an toàn.",options:["Dùng kéo đầu tròn","Ngồi ngay ngắn","Cầm kéo chạy nhảy","Cất kéo khi dùng xong"],answers:[0,1,3]},{id:"cn3-vat-lieu-dung-cu-16",type:"mc",q:"Làm thủ công xong, giấy vụn để ở đâu?",emoji:"🗑️",explain:"Giấy vụn bỏ vào thùng rác để lớp học sạch sẽ.",options:["Dưới gầm bàn","Ngoài cửa sổ","Vào thùng rác","Trên ghế bạn"],answer:2},{id:"cn3-vat-lieu-dung-cu-17",type:"tf",q:"Kéo cho học sinh nhỏ nên là loại đầu tròn.",emoji:"✂️",explain:"Đúng. Kéo đầu tròn ít gây đâm vào tay hơn kéo đầu nhọn.",answer:!0},{id:"cn3-vat-lieu-dung-cu-18",type:"mc",q:"Dụng cụ nào dùng để đo độ dài mảnh bìa?",emoji:"📏",explain:"Thước kẻ có vạch chia xăng-ti-mét để đo độ dài.",options:["Hồ dán","Cái kéo","Thước kẻ","Giấy màu"],answer:2}]},{questions:[{id:"cn3-vat-lieu-dung-cu-19",type:"mc",q:"Minh cần làm một tấm thiệp đứng được. Minh nên chọn vật liệu nào?",emoji:"💌",explain:"Bìa cứng dày và chắc nên tấm thiệp đứng vững.",options:["Bìa cứng","Giấy ăn","Túi ni lông","Lá cây khô"],answer:0},{id:"cn3-vat-lieu-dung-cu-20",type:"order",q:"Sắp xếp các việc khi làm thủ công.",explain:"Chuẩn bị đồ dùng, làm sản phẩm, rồi thu dọn và rửa tay.",items:["Chuẩn bị vật liệu, dụng cụ","Đo, kẻ, cắt, dán","Cất dụng cụ, thu dọn giấy vụn","Rửa tay sạch sẽ"]},{id:"cn3-vat-lieu-dung-cu-21",type:"mc",q:"Lan lỡ làm hồ dán dính vào mắt. Lan nên làm gì?",emoji:"👁️",explain:"Báo ngay người lớn để được rửa mắt bằng nước sạch, không dụi mắt.",options:["Dụi mắt thật mạnh","Báo ngay người lớn","Không nói với ai","Nhắm mắt đi ngủ"],answer:1},{id:"cn3-vat-lieu-dung-cu-22",type:"tf",q:"Em nên dùng vỏ hộp đã rửa sạch, phơi khô để làm thủ công.",emoji:"🧃",explain:"Đúng. Vỏ hộp sạch, khô thì không bẩn, không có mùi và dễ dán.",answer:!0},{id:"cn3-vat-lieu-dung-cu-23",type:"mc",q:"Bạn Nam để kéo mở lưỡi trên mép bàn. Em nên làm gì?",emoji:"✂️",explain:"Khép kéo lại và cất vào hộp để không ai bị đứt tay hay kéo rơi.",options:["Mặc kệ cái kéo","Khép kéo, cất vào hộp","Cầm kéo đi chơi","Đẩy kéo xuống đất"],answer:1},{id:"cn3-vat-lieu-dung-cu-24",type:"multi",q:"Đâu là vật liệu tái chế có thể làm thủ công?",explain:"Vỏ hộp sữa, lõi giấy vệ sinh, nắp chai sạch đều dùng lại được.",options:["Vỏ hộp sữa sạch","Lõi giấy vệ sinh","Mảnh thủy tinh vỡ","Nắp chai sạch"],answers:[0,1,3]},{id:"cn3-vat-lieu-dung-cu-25",type:"tf",q:"Mảnh thủy tinh vỡ là vật liệu tốt để làm đồ thủ công.",emoji:"⚠️",explain:"Sai. Thủy tinh vỡ rất sắc, dễ làm đứt tay.",answer:!1},{id:"cn3-vat-lieu-dung-cu-26",type:"mc",q:"Muốn dán giấy cho phẳng, em làm thế nào?",emoji:"🧴",explain:"Bôi một lớp hồ mỏng, đều rồi miết nhẹ cho giấy phẳng.",options:["Bôi thật nhiều hồ","Không cần bôi hồ","Bôi hồ mỏng, miết nhẹ","Vò giấy rồi dán"],answer:2}]}],challenge:{questions:[{id:"cn3-vat-lieu-dung-cu-27",type:"mc",q:"Chi cần làm cột cờ nhỏ, nhẹ, dài và thẳng. Vật liệu nào hợp nhất?",emoji:"🚩",explain:"Ống hút hoặc que gỗ nhỏ dài, thẳng, nhẹ nên làm cột cờ tốt.",options:["Giấy ăn","Nắp chai","Ống hút","Cục tẩy"],answer:2},{id:"cn3-vat-lieu-dung-cu-28",type:"multi",q:"Bạn nào làm thủ công chưa an toàn?",explain:"Chĩa mũi kéo vào bạn và nếm hồ dán là không an toàn.",options:["Hà chĩa mũi kéo vào bạn","Tùng nếm thử hồ dán","Vy cất kéo vào hộp","Bình ngồi ngay ngắn"],answers:[0,1]},{id:"cn3-vat-lieu-dung-cu-29",type:"match",q:"Nối việc cần làm với dụng cụ phù hợp.",explain:"Đo bằng thước, kẻ bằng bút chì, cắt bằng kéo, dán bằng hồ.",pairs:[["Đo độ dài","Thước kẻ"],["Vẽ nét nhẹ","Bút chì"],["Cắt bìa","Cái kéo"],["Dán giấy","Hồ dán"]]},{id:"cn3-vat-lieu-dung-cu-30",type:"tf",q:"Cắt bìa dày quá sức, em nên nhờ người lớn giúp.",emoji:"🙋",explain:"Đúng. Cố cắt bìa quá dày dễ trượt kéo và đứt tay.",answer:!0},{id:"cn3-vat-lieu-dung-cu-31",type:"fill",q:"Khi đưa kéo cho bạn, em đưa phần … kéo về phía bạn.",emoji:"✂️",explain:"Đưa cán kéo về phía bạn để bạn cầm an toàn.",answer:["cán"]},{id:"cn3-vat-lieu-dung-cu-20",type:"order",q:"Sắp xếp các việc khi làm thủ công.",explain:"Chuẩn bị đồ dùng, làm sản phẩm, rồi thu dọn và rửa tay.",items:["Chuẩn bị vật liệu, dụng cụ","Đo, kẻ, cắt, dán","Cất dụng cụ, thu dọn giấy vụn","Rửa tay sạch sẽ"]},{id:"cn3-vat-lieu-dung-cu-32",type:"mc",q:"Vì sao nên dùng lại vỏ hộp để làm đồ dùng?",emoji:"♻️",explain:"Dùng lại vỏ hộp giúp giảm rác thải và tiết kiệm.",options:["Để nhà bừa bộn","Giảm rác, tiết kiệm","Để hộp bẩn hơn","Vì kéo thích hộp"],answer:1}]},summary:["Vật liệu làm thủ công gồm giấy màu, bìa cứng, vỏ hộp, ống hút và nhiều thứ khác.","Dụng cụ làm thủ công gồm thước kẻ, bút chì, kéo, hồ dán.","Em dùng kéo cẩn thận, không nếm hồ dán, làm xong thì thu dọn và rửa tay."]},{id:"cn3-thuoc-ke",title:"Làm thước kẻ bằng bìa",weeks:[19,20],learn:[{title:"Thước kẻ dùng để làm gì?",text:"Thước kẻ giúp em kẻ đường thẳng và đo độ dài. Trên thước có các vạch chia và chữ số.",example:"📏 0  1  2  3  4  5 … cm"},{title:"Chuẩn bị",text:"Em cần một mảnh bìa cứng, thước kẻ mẫu, bút chì, kéo, bút màu để trang trí.",example:"📦 bìa  ·  📏 thước mẫu  ·  ✏️ bút chì  ·  ✂️ kéo"},{title:"Các bước làm",text:"Kẻ một hình chữ nhật lên bìa, cắt theo nét kẻ, rồi dùng thước mẫu đánh dấu các vạch cách đều nhau và ghi số.",example:"▭ kẻ  ➜  ✂️ cắt  ➜  📏 đánh dấu vạch  ➜  🔢 ghi số"}],practice:[{questions:[{id:"cn3-thuoc-ke-01",type:"mc",q:"Thước kẻ giúp em làm gì?",emoji:"📏",explain:"Thước kẻ dùng để kẻ đường thẳng và đo độ dài.",options:["Cắt giấy","Kẻ và đo","Tô màu","Dán giấy"],answer:1},{id:"cn3-thuoc-ke-02",type:"mc",q:"Thân thước kẻ bằng bìa thường có hình gì?",emoji:"▭",explain:"Thước kẻ thường là hình chữ nhật dài và hẹp.",options:["Hình chữ nhật","Hình tam giác","Hình tròn","Hình trái tim"],answer:0},{id:"cn3-thuoc-ke-03",type:"tf",q:"Làm thước kẻ cần dùng bìa cứng để thước thẳng, không bị cong.",emoji:"📦",explain:"Đúng. Bìa cứng giữ thước thẳng khi kẻ.",answer:!0},{id:"cn3-thuoc-ke-04",type:"multi",q:"Làm thước kẻ bằng bìa, em cần chuẩn bị gì?",explain:"Cần bìa cứng, bút chì, kéo và một thước mẫu để đánh dấu vạch.",options:["Bìa cứng","Bút chì","Cái kéo","Nồi cơm"],answers:[0,1,2]},{id:"cn3-thuoc-ke-05",type:"tf",q:"Các vạch chia trên thước phải cách đều nhau.",emoji:"📏",explain:"Đúng. Vạch cách đều thì thước mới đo đúng.",answer:!0},{id:"cn3-thuoc-ke-06",type:"mc",q:"Bước đầu tiên khi làm thước kẻ bằng bìa là gì?",emoji:"✏️",explain:"Đầu tiên em kẻ hình chữ nhật lên bìa, sau đó mới cắt.",options:["Kẻ hình lên bìa","Ghi số lên thước","Trang trí thước","Đem thước đi đo"],answer:0},{id:"cn3-thuoc-ke-07",type:"fill",q:"Vạch đầu tiên trên thước kẻ ghi số … .",emoji:"🔢",explain:"Thước kẻ bắt đầu từ vạch số 0.",answer:["0","không"]},{id:"cn3-thuoc-ke-08",type:"mc",q:"Em dùng gì để đánh dấu vạch cho đều?",emoji:"📏",explain:"Đặt thước mẫu cạnh mảnh bìa để chấm các vạch cho đều.",options:["Một thước mẫu","Ngón tay cái","Hồ dán","Cục tẩy"],answer:0},{id:"cn3-thuoc-ke-09",type:"tf",q:"Thước kẻ bằng bìa không cần cắt thẳng.",emoji:"✂️",explain:"Sai. Cạnh thước phải thẳng thì mới kẻ được đường thẳng.",answer:!1}]},{questions:[{id:"cn3-thuoc-ke-10",type:"order",q:"Sắp xếp các bước làm thước kẻ bằng bìa.",explain:"Kẻ hình, cắt, đánh dấu vạch, ghi số rồi trang trí.",items:["Kẻ hình chữ nhật lên bìa","Cắt theo nét kẻ","Đánh dấu các vạch chia","Ghi số và trang trí"]},{id:"cn3-thuoc-ke-11",type:"mc",q:"Vì sao cạnh thước kẻ phải thật thẳng?",emoji:"📏",explain:"Cạnh thẳng giúp kẻ ra đường thẳng.",options:["Để thước nặng hơn","Để thước dài hơn","Để thước có màu","Để kẻ đường thẳng"],answer:3},{id:"cn3-thuoc-ke-12",type:"tf",q:"Nếu vạch chia không đều, thước sẽ đo sai.",emoji:"❌",explain:"Đúng. Vạch lệch thì số đo đọc được sẽ không đúng.",answer:!0},{id:"cn3-thuoc-ke-13",type:"mc",q:"Nên cắt thước theo nét kẻ như thế nào?",emoji:"✂️",explain:"Cắt chậm, đúng theo nét kẻ để cạnh thước thẳng.",options:["Cắt nhanh, bỏ nét","Xé bằng tay","Cắt chậm, theo nét","Cắt chéo tùy ý"],answer:2},{id:"cn3-thuoc-ke-14",type:"match",q:"Nối bước làm với dụng cụ dùng ở bước đó.",explain:"Kẻ dùng bút chì, cắt dùng kéo, trang trí dùng bút màu.",pairs:[["Kẻ hình","Bút chì"],["Cắt bìa","Cái kéo"],["Trang trí","Bút màu"]]},{id:"cn3-thuoc-ke-15",type:"multi",q:"Thước kẻ bằng bìa làm tốt cần có gì?",explain:"Thước tốt có cạnh thẳng, vạch đều và số rõ ràng.",options:["Cạnh thẳng","Vạch chia đều","Số rõ ràng","Bị cong vênh"],answers:[0,1,2]},{id:"cn3-thuoc-ke-16",type:"mc",q:"Thước làm bằng giấy mỏng sẽ thế nào?",emoji:"📄",explain:"Giấy mỏng dễ cong, dễ rách nên khó kẻ.",options:["Rất chắc chắn","Nặng như sắt","Dễ cong, dễ rách","Không cắt được"],answer:2},{id:"cn3-thuoc-ke-17",type:"tf",q:"Em nên ghi số lên thước trước khi cắt bìa.",emoji:"🔢",explain:"Sai. Em cắt thước xong rồi mới đánh dấu vạch và ghi số.",answer:!1},{id:"cn3-thuoc-ke-18",type:"mc",q:"Trang trí thước kẻ để làm gì?",emoji:"🎨",explain:"Trang trí giúp thước đẹp hơn, em thích dùng hơn.",options:["Để thước đo sai","Để thước đẹp hơn","Để thước gãy","Để bỏ thước đi"],answer:1}]},{questions:[{id:"cn3-thuoc-ke-19",type:"mc",q:"Thước của Bình bị cong. Lí do có thể là gì?",emoji:"〰️",explain:"Bìa quá mỏng hoặc bị ướt sẽ làm thước cong.",options:["Bìa mỏng, bị ướt","Ghi số quá rõ","Vạch quá đều","Cạnh quá thẳng"],answer:0},{id:"cn3-thuoc-ke-20",type:"mc",q:"Vạch số 2 trên thước của Thảo lệch xa hơn các vạch khác. Thảo nên làm gì?",emoji:"📏",explain:"Thảo tẩy vạch sai rồi dùng thước mẫu đánh dấu lại.",options:["Kệ vạch đó","Bỏ vạch số 2","Tẩy, đánh dấu lại","Vẽ thêm hoa"],answer:2},{id:"cn3-thuoc-ke-21",type:"tf",q:"Dùng thước mẫu để chấm vạch sẽ giúp vạch đều hơn ước lượng bằng mắt.",emoji:"👀",explain:"Đúng. Ước lượng bằng mắt dễ sai, thước mẫu cho vạch chính xác hơn.",answer:!0},{id:"cn3-thuoc-ke-22",type:"multi",q:"Làm xong thước, em cần làm gì?",explain:"Thu dọn giấy vụn, cất kéo và kiểm tra thước bằng cách kẻ thử.",options:["Thu dọn giấy vụn","Cất kéo cẩn thận","Kẻ thử một đường","Vứt bìa thừa xuống sàn"],answers:[0,1,2]},{id:"cn3-thuoc-ke-23",type:"mc",q:"Để thử thước có thẳng không, em làm gì?",emoji:"✏️",explain:"Kẻ thử một đường, nếu đường thẳng thì cạnh thước thẳng.",options:["Ngửi cái thước","Bẻ cong thước","Kẻ thử một đường","Ngâm thước vào nước"],answer:2},{id:"cn3-thuoc-ke-24",type:"order",q:"Sắp xếp cách đánh dấu vạch chia trên thước bìa.",explain:"Đặt thước mẫu sát cạnh, chấm vạch theo thước mẫu rồi kẻ vạch và ghi số.",items:["Đặt thước mẫu sát cạnh bìa","Chấm điểm theo vạch thước mẫu","Kẻ các vạch ngắn","Ghi số dưới mỗi vạch"]},{id:"cn3-thuoc-ke-25",type:"tf",q:"Chỗ bìa thừa sau khi cắt có thể giữ lại để làm đồ dùng khác.",emoji:"♻️",explain:"Đúng. Bìa thừa còn dùng được thì giữ lại, tránh lãng phí.",answer:!0},{id:"cn3-thuoc-ke-26",type:"mc",q:"Ngọc muốn thước bền, ít bị bẩn. Ngọc có thể làm gì?",emoji:"📏",explain:"Bọc một lớp băng dính trong giúp thước bền và ít bẩn.",options:["Để thước ngoài mưa","Bọc băng dính trong","Bẻ đôi cái thước","Bôi hồ khắp thước"],answer:1}]}],challenge:{questions:[{id:"cn3-thuoc-ke-27",type:"mc",q:"Khoa muốn thước dài 15 xăng-ti-mét. Khoa phải kẻ mảnh bìa thế nào?",emoji:"📏",explain:"Thước dài 15 xăng-ti-mét thì mảnh bìa phải dài ít nhất 15 xăng-ti-mét.",options:["Không cần đo","Dài đúng 5 cm","Dài khoảng 10 cm","Dài ít nhất 15 cm"],answer:3},{id:"cn3-thuoc-ke-10",type:"order",q:"Sắp xếp các bước làm thước kẻ bằng bìa.",explain:"Kẻ hình, cắt, đánh dấu vạch, ghi số rồi trang trí.",items:["Kẻ hình chữ nhật lên bìa","Cắt theo nét kẻ","Đánh dấu các vạch chia","Ghi số và trang trí"]},{id:"cn3-thuoc-ke-28",type:"multi",q:"Lỗi nào làm thước bìa dùng không tốt?",explain:"Cạnh lượn sóng, vạch không đều và bìa quá mỏng đều làm thước kém.",options:["Cạnh lượn sóng","Vạch không đều","Bìa quá mỏng","Số viết rõ ràng"],answers:[0,1,2]},{id:"cn3-thuoc-ke-29",type:"tf",q:"Trên thước xăng-ti-mét, hai vạch có ghi số liền nhau cách nhau 1 xăng-ti-mét.",emoji:"📏",explain:"Đúng. Các vạch có ghi số liền nhau cách nhau 1 xăng-ti-mét.",answer:!0},{id:"cn3-thuoc-ke-30",type:"fill",q:"Muốn kẻ đường thẳng, em đặt bút chì sát … thước.",emoji:"✏️",explain:"Đặt bút sát cạnh thước rồi kẻ để có đường thẳng.",answer:["cạnh","mép"]},{id:"cn3-thuoc-ke-31",type:"mc",q:"Vì sao nên kẻ bằng bút chì rồi mới tô bút mực?",emoji:"🖊️",explain:"Nét chì kẻ sai thì tẩy được, đúng rồi mới tô mực.",options:["Vì mực không viết","Vì chì sai tẩy được","Vì chì đắt hơn","Vì chì thơm hơn"],answer:1},{id:"cn3-thuoc-ke-32",type:"match",q:"Nối lỗi với cách sửa.",explain:"Mỗi lỗi có một cách sửa phù hợp.",pairs:[["Vạch bị lệch","Tẩy, chấm lại"],["Thước bị cong","Dùng bìa dày hơn"],["Số bị mờ","Tô số đậm hơn"]]}]},summary:["Thước kẻ giúp em kẻ đường thẳng và đo độ dài.","Làm thước bằng bìa: kẻ hình chữ nhật, cắt theo nét kẻ, đánh dấu vạch đều, ghi số và trang trí.","Thước tốt có cạnh thẳng, vạch chia đều, số rõ ràng."]},{id:"cn3-ong-but",title:"Làm ống đựng bút",weeks:[21,22],learn:[{title:"Ống đựng bút giúp gì cho em?",text:"Ống đựng bút giữ bút, thước gọn gàng trên bàn học, giúp em dễ tìm đồ dùng.",example:"🖊️✏️🖍️ ➜ 🫙 gọn gàng"},{title:"Vật liệu dùng lại",text:"Em có thể dùng lõi giấy, vỏ hộp hoặc lon sạch đã được người lớn làm nhẵn miệng, cùng giấy màu, bìa và hồ dán.",example:"🧻 lõi giấy  ·  📦 vỏ hộp  ·  📄 giấy màu"},{title:"Các bước làm",text:"Cắt bìa làm đáy, dán đáy vào thân ống, bọc giấy màu quanh thân rồi trang trí theo ý em.",example:"⭕ đáy  ➜  🧴 dán  ➜  📄 bọc giấy  ➜  🎨 trang trí"}],practice:[{questions:[{id:"cn3-ong-but-01",type:"mc",q:"Ống đựng bút dùng để làm gì?",emoji:"🖊️",explain:"Ống đựng bút giữ bút, thước gọn gàng.",options:["Đựng nước uống","Đựng cơm","Đựng bút, thước","Đựng quần áo"],answer:2},{id:"cn3-ong-but-02",type:"tf",q:"Lõi giấy vệ sinh có thể dùng làm thân ống đựng bút.",emoji:"🧻",explain:"Đúng. Lõi giấy là ống rỗng, cứng vừa phải để làm thân.",answer:!0},{id:"cn3-ong-but-03",type:"mc",q:"Phần nào giữ cho bút không rơi xuống dưới?",emoji:"⭕",explain:"Đáy ống chặn bên dưới để bút không rơi ra.",options:["Hoa trang trí","Đáy ống","Giấy màu bọc ngoài","Tên của em"],answer:1},{id:"cn3-ong-but-04",type:"multi",q:"Vật nào có thể dùng làm thân ống đựng bút?",explain:"Lõi giấy, vỏ hộp giấy sạch đều có thể làm thân ống.",options:["Lõi giấy","Vỏ hộp giấy sạch","Quả bóng bay","Chiếc lá"],answers:[0,1]},{id:"cn3-ong-but-05",type:"tf",q:"Ống đựng bút cần có đáy chắc chắn.",emoji:"🫙",explain:"Đúng. Đáy chắc thì ống đứng vững và giữ được bút.",answer:!0},{id:"cn3-ong-but-06",type:"fill",q:"Em bọc giấy … quanh thân ống cho đẹp.",emoji:"📄",explain:"Giấy màu bọc ngoài làm ống đựng bút đẹp hơn.",answer:["màu"]},{id:"cn3-ong-but-07",type:"mc",q:"Em dùng gì để gắn đáy vào thân ống?",emoji:"🧴",explain:"Hồ dán hoặc băng dính giúp gắn đáy vào thân.",options:["Cục tẩy","Hồ dán","Thước kẻ","Bút chì"],answer:1},{id:"cn3-ong-but-08",type:"tf",q:"Làm ống đựng bút phải mua đồ mới, không dùng lại đồ cũ được.",emoji:"♻️",explain:"Sai. Em có thể dùng lại lõi giấy, vỏ hộp sạch.",answer:!1},{id:"cn3-ong-but-09",type:"mc",q:"Đáy ống đựng bút hình tròn thì em cắt bìa hình gì?",emoji:"⭕",explain:"Thân ống tròn thì đáy cũng cắt hình tròn cho vừa.",options:["Hình tròn","Hình ngôi sao","Hình tam giác","Hình chữ nhật dài"],answer:0}]},{questions:[{id:"cn3-ong-but-10",type:"order",q:"Sắp xếp các bước làm ống đựng bút từ lõi giấy.",explain:"Đo và cắt đáy, dán đáy, bọc giấy màu rồi trang trí.",items:["Đặt lõi lên bìa, vẽ và cắt đáy","Dán đáy vào lõi giấy","Bọc giấy màu quanh thân","Trang trí ống bút"]},{id:"cn3-ong-but-11",type:"mc",q:"Muốn đáy vừa với thân ống, em làm thế nào?",emoji:"✏️",explain:"Đặt miệng ống lên bìa và vẽ theo vòng miệng ống để đáy vừa khít.",options:["Cắt đại một hình","Dùng lá cây làm đáy","Không cần đáy","Vẽ theo miệng ống"],answer:3},{id:"cn3-ong-but-12",type:"tf",q:"Đợi hồ khô rồi mới cắm bút vào ống là đúng.",emoji:"⏳",explain:"Đúng. Hồ khô thì đáy mới dính chắc.",answer:!0},{id:"cn3-ong-but-13",type:"mc",q:"Vì sao nên dùng vỏ hộp đã rửa sạch, phơi khô?",emoji:"🧃",explain:"Vỏ hộp sạch, khô không có mùi, không bẩn bút và dễ dán.",options:["Để hộp bị ướt","Để hộp nặng hơn","Sạch, không có mùi","Để hồ không dính"],answer:2},{id:"cn3-ong-but-14",type:"match",q:"Nối phần của ống đựng bút với việc nó làm.",explain:"Thân để chứa bút, đáy để giữ bút, phần trang trí làm ống đẹp.",pairs:[["Thân ống","Chứa bút"],["Đáy ống","Giữ bút không rơi"],["Hình trang trí","Làm ống đẹp"]]},{id:"cn3-ong-but-15",type:"tf",q:"Miệng lon kim loại sắc có thể dùng ngay mà không cần người lớn giúp.",emoji:"⚠️",explain:"Sai. Miệng lon sắc dễ cứa tay, phải nhờ người lớn làm nhẵn hoặc chọn vật khác.",answer:!1},{id:"cn3-ong-but-16",type:"multi",q:"Ống đựng bút làm tốt có đặc điểm gì?",explain:"Ống tốt đứng vững, đáy chắc, đựng được bút và gọn đẹp.",options:["Đứng vững","Đáy chắc","Đựng được bút","Bị đổ liên tục"],answers:[0,1,2]},{id:"cn3-ong-but-17",type:"mc",q:"Ống bút quá thấp thì bút sẽ thế nào?",emoji:"🖊️",explain:"Ống quá thấp thì bút dài dễ bị đổ ra ngoài.",options:["Biến mất","Đứng rất vững","Tự viết chữ","Dễ bị đổ ra"],answer:3},{id:"cn3-ong-but-18",type:"mc",q:"Bước cuối cùng khi làm ống đựng bút là gì?",emoji:"🎨",explain:"Làm xong thân và đáy, em trang trí và thu dọn chỗ ngồi.",options:["Cắt đáy","Chọn lõi giấy","Trang trí, thu dọn","Vẽ theo miệng ống"],answer:2}]},{questions:[{id:"cn3-ong-but-19",type:"mc",q:"Ống đựng bút của Phúc hay bị đổ. Phúc nên làm gì?",emoji:"🫙",explain:"Làm đáy rộng, chắc hơn giúp ống đứng vững.",options:["Bỏ đáy đi","Bọc thêm giấy mỏng","Làm đáy rộng, chắc","Cắm bút ngược"],answer:2},{id:"cn3-ong-but-20",type:"multi",q:"Vật nào có thể dùng để trang trí ống đựng bút?",explain:"Giấy màu, hình dán, bút màu đều trang trí được.",options:["Giấy màu","Hình dán","Bút màu","Mảnh kính vỡ"],answers:[0,1,2]},{id:"cn3-ong-but-21",type:"tf",q:"Em có thể làm ống bút có hai ngăn để đựng riêng bút và thước.",emoji:"✨",explain:"Đúng. Ghép hai lõi giấy cạnh nhau sẽ có hai ngăn.",answer:!0},{id:"cn3-ong-but-22",type:"mc",q:"Vy muốn đựng cả thước dài 20 xăng-ti-mét. Ống bút nên thế nào?",emoji:"📏",explain:"Ống cao hơn giúp thước dài đứng vững, không đổ.",options:["Không có đáy","Thật thấp","Cao hơn, đáy chắc","Rất nhỏ"],answer:2},{id:"cn3-ong-but-23",type:"order",q:"Sắp xếp các bước bọc giấy màu quanh thân ống.",explain:"Đo và cắt giấy, bôi hồ, cuốn giấy quanh ống rồi miết phẳng.",items:["Đo và cắt giấy màu vừa thân ống","Bôi hồ mỏng lên mặt sau giấy","Cuốn giấy quanh thân ống","Miết nhẹ cho giấy phẳng"]},{id:"cn3-ong-but-24",type:"tf",q:"Đặt ống đựng bút ở góc bàn học giúp bàn gọn gàng hơn.",emoji:"🧹",explain:"Đúng. Bút được cất một chỗ, bàn học gọn gàng.",answer:!0},{id:"cn3-ong-but-25",type:"mc",q:"Giấy màu bọc bị nhăn. Lí do có thể là gì?",emoji:"📄",explain:"Bôi hồ quá nhiều, không đều làm giấy bị nhăn.",options:["Bôi hồ quá nhiều","Giấy quá đẹp","Ống quá sạch","Đáy quá chắc"],answer:0},{id:"cn3-ong-but-26",type:"mc",q:"Dùng lại lõi giấy làm ống bút có lợi gì?",emoji:"♻️",explain:"Dùng lại đồ cũ giúp giảm rác và tiết kiệm tiền.",options:["Tốn tiền hơn","Làm bàn bừa bộn","Làm bút hỏng","Giảm rác, tiết kiệm"],answer:3}]}],challenge:{questions:[{id:"cn3-ong-but-27",type:"mc",q:"Hà dùng giấy ăn mỏng làm đáy ống bút. Điều gì dễ xảy ra?",emoji:"🧻",explain:"Giấy ăn mỏng, yếu nên bút dễ chọc thủng đáy.",options:["Đáy rất bền","Bút đổi màu","Ống cao lên","Bút chọc thủng đáy"],answer:3},{id:"cn3-ong-but-10",type:"order",q:"Sắp xếp các bước làm ống đựng bút từ lõi giấy.",explain:"Đo và cắt đáy, dán đáy, bọc giấy màu rồi trang trí.",items:["Đặt lõi lên bìa, vẽ và cắt đáy","Dán đáy vào lõi giấy","Bọc giấy màu quanh thân","Trang trí ống bút"]},{id:"cn3-ong-but-28",type:"multi",q:"Bạn nào làm ống đựng bút an toàn, gọn gàng?",explain:"Nhờ người lớn với vật sắc, cất kéo và thu dọn là việc làm đúng.",options:["An nhờ mẹ mài nhẵn miệng lon","Lan cất kéo sau khi cắt","Dũng để giấy vụn khắp sàn","Chi thu dọn bàn học"],answers:[0,1,3]},{id:"cn3-ong-but-29",type:"tf",q:"Đáy bằng bìa cứng chắc hơn đáy bằng giấy ăn.",emoji:"📦",explain:"Đúng. Bìa cứng dày nên chịu được sức nặng của bút.",answer:!0},{id:"cn3-ong-but-30",type:"fill",q:"Hồ chưa … mà đã cắm bút thì đáy dễ bị bung.",emoji:"⏳",explain:"Phải đợi hồ khô thì đáy mới dính chắc.",answer:["khô"]},{id:"cn3-ong-but-31",type:"match",q:"Nối vấn đề với cách khắc phục.",explain:"Mỗi vấn đề có một cách sửa phù hợp.",pairs:[["Ống hay bị đổ","Làm đáy rộng hơn"],["Đáy bị bung","Dán lại, đợi khô"],["Giấy bị nhăn","Bôi hồ mỏng, đều"]]},{id:"cn3-ong-but-32",type:"mc",q:"Tùng muốn tặng bạn một ống bút. Tùng nên làm gì để ống đẹp, bền?",emoji:"🎁",explain:"Chọn vật liệu chắc, dán cẩn thận rồi trang trí gọn gàng.",options:["Không làm đáy","Làm vội cho nhanh","Chọn đồ chắc, dán kĩ","Dùng giấy ướt"],answer:2}]},summary:["Ống đựng bút giúp bút, thước gọn gàng trên bàn học.","Có thể dùng lại lõi giấy, vỏ hộp sạch; vật có cạnh sắc phải nhờ người lớn giúp.","Các bước: cắt đáy, dán đáy vào thân, bọc giấy màu, trang trí và thu dọn."]}]},{id:"bien-bao-giao-thong",title:"Làm biển báo giao thông",lessons:[{id:"cn3-bien-bao",title:"Tìm hiểu biển báo giao thông",weeks:[23,25],learn:[{title:"Biển báo giao thông là gì?",text:"Biển báo giao thông đặt bên đường, cho người đi đường biết điều cần làm hoặc điều cần chú ý để đi lại an toàn.",example:"🚸 🚫 ⚠️ ➡️"},{title:"Biển báo cấm và biển báo nguy hiểm",text:"Biển báo cấm thường có hình tròn, viền đỏ, nền trắng, cho biết điều không được làm. Biển báo nguy hiểm có hình tam giác, viền đỏ, nền vàng, nhắc em chú ý.",example:"⭕ cấm  ·  🔺 nguy hiểm, cảnh báo"},{title:"Biển hiệu lệnh và biển chỉ dẫn",text:"Biển hiệu lệnh có hình tròn, nền xanh lam, cho biết điều phải làm theo. Biển chỉ dẫn thường có hình vuông hoặc chữ nhật, nền xanh lam, cho biết thông tin cần thiết.",example:"🔵 hiệu lệnh  ·  🟦 chỉ dẫn"}],practice:[{questions:[{id:"cn3-bien-bao-01",type:"mc",q:"Biển báo giao thông giúp người đi đường điều gì?",emoji:"🚦",explain:"Biển báo cho biết điều cần làm hoặc cần chú ý để đi lại an toàn.",options:["Đi nhanh hơn","Bán hàng","Trang trí đường","Đi lại an toàn"],answer:3},{id:"cn3-bien-bao-02",type:"mc",q:"Biển báo nguy hiểm có hình gì?",emoji:"🔺",explain:"Biển báo nguy hiểm có hình tam giác, viền đỏ, nền vàng.",options:["Hình tam giác","Hình tròn","Hình vuông","Hình ngôi sao"],answer:0},{id:"cn3-bien-bao-03",type:"mc",q:"Biển báo cấm thường có hình gì?",emoji:"⭕",explain:"Biển báo cấm thường có hình tròn, viền đỏ.",options:["Hình tam giác","Hình tròn","Hình thoi","Hình chữ nhật"],answer:1},{id:"cn3-bien-bao-04",type:"tf",q:"Biển báo nguy hiểm có nền màu vàng.",emoji:"🔺",explain:"Đúng. Biển báo nguy hiểm có nền vàng, viền đỏ.",answer:!0},{id:"cn3-bien-bao-05",type:"tf",q:"Biển hiệu lệnh có nền màu đỏ.",emoji:"🔵",explain:"Sai. Biển hiệu lệnh có hình tròn, nền xanh lam.",answer:!1},{id:"cn3-bien-bao-06",type:"match",q:"Nối nhóm biển báo với hình dạng của nó.",explain:"Biển cấm hình tròn viền đỏ, biển nguy hiểm hình tam giác, biển chỉ dẫn hình vuông hoặc chữ nhật.",pairs:[["Biển báo cấm","Tròn, viền đỏ"],["Biển báo nguy hiểm","Tam giác, nền vàng"],["Biển chỉ dẫn","Vuông, nền xanh"]]},{id:"cn3-bien-bao-07",type:"fill",q:"Biển hiệu lệnh có hình tròn, nền màu xanh … .",emoji:"🔵",explain:"Biển hiệu lệnh có nền xanh lam.",answer:["lam"]},{id:"cn3-bien-bao-08",type:"mc",q:"Biển báo cấm cho người đi đường biết điều gì?",emoji:"🚫",explain:"Biển báo cấm cho biết điều không được làm.",options:["Điều phải làm","Chỗ bán đồ ăn","Tên con đường","Điều không được làm"],answer:3},{id:"cn3-bien-bao-09",type:"tf",q:"Biển báo giao thông được đặt ở bên đường để mọi người dễ nhìn thấy.",emoji:"🛣️",explain:"Đúng. Biển đặt bên đường, ở chỗ dễ thấy.",answer:!0}]},{questions:[{id:"cn3-bien-bao-10",type:"mc",q:"Biển hình tròn, viền đỏ, nền trắng, có hình người đi bộ bị gạch chéo nghĩa là gì?",emoji:"🚷",explain:"Đó là biển cấm người đi bộ.",options:["Có trường học","Nơi đỗ xe","Đường cho xe đạp","Cấm người đi bộ"],answer:3},{id:"cn3-bien-bao-11",type:"mc",q:"Biển tam giác, viền đỏ, nền vàng, có hình hai bạn nhỏ báo điều gì?",emoji:"🚸",explain:"Đó là biển báo nguy hiểm “Trẻ em”, nhắc xe đi chậm, chú ý trẻ em.",options:["Cấm trẻ em","Chú ý trẻ em","Sân chơi trẻ em","Nhà trẻ đóng cửa"],answer:1},{id:"cn3-bien-bao-12",type:"tf",q:"Biển hình tròn, nền đỏ, có vạch ngang màu trắng là biển cấm đi ngược chiều.",emoji:"⛔",explain:"Đúng. Biển này cấm các xe đi vào theo chiều đặt biển.",answer:!0},{id:"cn3-bien-bao-13",type:"match",q:"Nối nhóm biển báo với ý nghĩa của nó.",explain:"Biển cấm báo điều không được làm, biển nguy hiểm nhắc chú ý, biển hiệu lệnh báo điều phải làm.",pairs:[["Biển báo cấm","Không được làm"],["Biển báo nguy hiểm","Cần chú ý"],["Biển hiệu lệnh","Phải làm theo"]]},{id:"cn3-bien-bao-14",type:"mc",q:"Biển hình tròn, nền xanh lam, có mũi tên trắng chỉ thẳng thuộc nhóm nào?",emoji:"⬆️",explain:"Hình tròn nền xanh lam là biển hiệu lệnh: xe phải đi theo hướng mũi tên.",options:["Biển hiệu lệnh","Biển quảng cáo","Biển nguy hiểm","Biển báo cấm"],answer:0},{id:"cn3-bien-bao-15",type:"multi",q:"Biển báo nguy hiểm có những đặc điểm nào?",explain:"Biển báo nguy hiểm hình tam giác, viền đỏ, nền vàng.",options:["Hình tam giác","Viền đỏ","Nền vàng","Nền xanh lam"],answers:[0,1,2]},{id:"cn3-bien-bao-16",type:"tf",q:"Biển báo cấm và biển hiệu lệnh có cùng màu nền.",emoji:"🎨",explain:"Sai. Biển cấm thường nền trắng viền đỏ, biển hiệu lệnh nền xanh lam.",answer:!1},{id:"cn3-bien-bao-17",type:"mc",q:"Biển tam giác vàng có hình đoàn tàu nhắc người đi đường điều gì?",emoji:"🚆",explain:"Đó là biển báo nguy hiểm: phía trước giao nhau với đường sắt, phải chú ý.",options:["Cấm đi tàu","Ga tàu bán vé","Chú ý đường sắt","Đồ chơi tàu hỏa"],answer:2},{id:"cn3-bien-bao-18",type:"mc",q:"Biển hình vuông, nền xanh lam, có chữ P trắng cho biết gì?",emoji:"🅿️",explain:"Đó là biển chỉ dẫn nơi đỗ xe.",options:["Nơi đỗ xe","Cấm đỗ xe","Có trường học","Đường cấm"],answer:0}]},{questions:[{id:"cn3-bien-bao-19",type:"mc",q:"Gần cổng trường có biển “Trẻ em”. Người lái xe nên làm gì?",emoji:"🚸",explain:"Biển nhắc chú ý trẻ em, người lái xe cần đi chậm, quan sát.",options:["Dừng xe giữa đường","Đi nhanh hơn","Bóp còi liên tục","Đi chậm, quan sát"],answer:3},{id:"cn3-bien-bao-20",type:"mc",q:"Đến đầu ngõ có biển cấm người đi bộ. Nam nên làm gì?",emoji:"🚷",explain:"Nam không đi bộ vào đường đó, chọn đường khác an toàn.",options:["Đi đường khác","Đứng chơi ở đó","Đi lùi vào đó","Chạy thật nhanh qua"],answer:0},{id:"cn3-bien-bao-21",type:"tf",q:"Nhìn thấy biển báo nguy hiểm, người đi đường cần chú ý quan sát hơn.",emoji:"⚠️",explain:"Đúng. Biển nguy hiểm báo trước chỗ cần cẩn thận.",answer:!0},{id:"cn3-bien-bao-22",type:"multi",q:"Biển nào thuộc nhóm biển báo nguy hiểm?",explain:"Biển “Trẻ em” và biển giao nhau với đường sắt có hình tam giác vàng, là biển nguy hiểm.",options:["Biển “Trẻ em”","Biển giao nhau với đường sắt","Biển cấm người đi bộ","Biển nơi đỗ xe"],answers:[0,1]},{id:"cn3-bien-bao-23",type:"mc",q:"Bố chở Lan đến đầu đường có biển cấm đi ngược chiều. Bố nên làm gì?",emoji:"⛔",explain:"Không đi vào đường đó, rẽ đi đường khác đúng luật.",options:["Rẽ đi đường khác","Bấm còi rồi đi vào","Đi vào thật nhanh","Tắt máy dắt vào"],answer:0},{id:"cn3-bien-bao-24",type:"tf",q:"Em được tự ý nhổ hoặc làm hỏng biển báo bên đường.",emoji:"🚫",explain:"Sai. Biển báo giúp mọi người an toàn, cần giữ gìn.",answer:!1},{id:"cn3-bien-bao-25",type:"match",q:"Nối biển báo với việc người đi đường nên làm.",explain:"Mỗi biển báo cho biết một việc cần làm để an toàn.",pairs:[["Biển “Trẻ em”","Đi chậm, chú ý"],["Biển cấm người đi bộ","Không đi bộ vào"],["Biển nơi đỗ xe","Đỗ xe ở đây"]]},{id:"cn3-bien-bao-26",type:"mc",q:"Vì sao biển báo dùng màu đỏ, vàng, xanh tươi sáng?",emoji:"👀",explain:"Màu tươi sáng giúp người đi đường nhìn thấy biển từ xa.",options:["Để biển đắt hơn","Để biển nặng hơn","Để chụp ảnh","Dễ nhìn từ xa"],answer:3}]}],challenge:{questions:[{id:"cn3-bien-bao-27",type:"mc",q:"Một biển hình tròn, viền đỏ, nền trắng. Đây có thể là nhóm biển nào?",emoji:"⭕",explain:"Hình tròn, viền đỏ, nền trắng là đặc điểm của biển báo cấm.",options:["Biển hiệu lệnh","Biển chỉ dẫn","Biển nguy hiểm","Biển báo cấm"],answer:3},{id:"cn3-bien-bao-28",type:"multi",q:"Biển nào có nền màu xanh lam?",explain:"Biển hiệu lệnh và biển chỉ dẫn có nền xanh lam.",options:["Biển hiệu lệnh","Biển báo nguy hiểm","Biển chỉ dẫn","Biển cấm người đi bộ"],answers:[0,2]},{id:"cn3-bien-bao-29",type:"match",q:"Nối biển báo với nhóm của nó.",explain:"Mỗi biển thuộc một nhóm theo hình dạng và màu sắc.",pairs:[["Biển cấm đi ngược chiều","Biển báo cấm"],["Biển “Trẻ em”","Biển nguy hiểm"],["Biển nơi đỗ xe","Biển chỉ dẫn"],["Biển mũi tên đi thẳng","Biển hiệu lệnh"]]},{id:"cn3-bien-bao-30",type:"tf",q:"Biển hiệu lệnh cho biết điều người đi đường phải làm theo.",emoji:"🔵",explain:"Đúng. Biển hiệu lệnh là lệnh phải thi hành.",answer:!0},{id:"cn3-bien-bao-31",type:"fill",q:"Biển báo nguy hiểm có hình … giác.",emoji:"🔺",explain:"Biển báo nguy hiểm có hình tam giác.",answer:["tam"]},{id:"cn3-bien-bao-10",type:"mc",q:"Biển hình tròn, viền đỏ, nền trắng, có hình người đi bộ bị gạch chéo nghĩa là gì?",emoji:"🚷",explain:"Đó là biển cấm người đi bộ.",options:["Có trường học","Nơi đỗ xe","Đường cho xe đạp","Cấm người đi bộ"],answer:3},{id:"cn3-bien-bao-32",type:"mc",q:"Minh thấy biển báo bên đường bị cây che khuất. Minh nên làm gì?",emoji:"🌳",explain:"Minh báo cho người lớn để họ báo nơi có trách nhiệm xử lí.",options:["Báo cho người lớn","Nhổ biển báo đi","Kệ, không sao","Trèo lên chặt cây"],answer:0}]},summary:["Biển báo giao thông giúp người đi đường biết điều cần làm, cần chú ý để đi lại an toàn.","Biển báo cấm thường hình tròn, viền đỏ, nền trắng; biển báo nguy hiểm hình tam giác, viền đỏ, nền vàng.","Biển hiệu lệnh hình tròn, nền xanh lam; biển chỉ dẫn hình vuông hoặc chữ nhật, nền xanh lam."]},{id:"cn3-lam-bien-bao",title:"Làm mô hình biển báo giao thông",weeks:[26,27],learn:[{title:"Mô hình biển báo gồm những phần nào?",text:"Một mô hình biển báo có ba phần: mặt biển, cột biển và đế giữ cho biển đứng vững.",example:"🔺 mặt biển  ·  🥢 cột  ·  ⭕ đế"},{title:"Chuẩn bị",text:"Em cần bìa cứng, giấy màu, bút màu, que gỗ nhỏ hoặc ống hút làm cột, đất nặn hoặc nắp chai làm đế, kéo và hồ dán.",example:"📦 bìa  ·  🖍️ bút màu  ·  🥤 ống hút  ·  🟢 đất nặn"},{title:"Các bước làm",text:"Vẽ và cắt mặt biển, tô màu đúng như biển thật, gắn mặt biển lên cột, rồi cắm cột vào đế cho đứng vững.",example:"✏️ vẽ  ➜  ✂️ cắt  ➜  🖍️ tô màu  ➜  🥢 gắn cột  ➜  ⭕ đế"}],practice:[{questions:[{id:"cn3-lam-bien-bao-01",type:"multi",q:"Mô hình biển báo gồm những phần nào?",explain:"Mô hình gồm mặt biển, cột biển và đế.",options:["Mặt biển","Cột biển","Đế","Bánh xe"],answers:[0,1,2]},{id:"cn3-lam-bien-bao-02",type:"mc",q:"Vật nào có thể dùng làm cột biển báo?",emoji:"🥤",explain:"Ống hút hoặc que gỗ nhỏ dài, thẳng nên làm cột tốt.",options:["Cục tẩy","Giấy ăn","Quả bóng","Ống hút"],answer:3},{id:"cn3-lam-bien-bao-03",type:"mc",q:"Phần nào giúp mô hình biển báo đứng vững?",emoji:"⭕",explain:"Đế giữ cho cột biển đứng vững.",options:["Đế","Mặt biển","Màu sơn","Mũi tên"],answer:0},{id:"cn3-lam-bien-bao-04",type:"tf",q:"Mặt biển báo nên làm bằng bìa cứng.",emoji:"📦",explain:"Đúng. Bìa cứng giữ mặt biển phẳng, không bị gập.",answer:!0},{id:"cn3-lam-bien-bao-05",type:"tf",q:"Khi làm mô hình, em có thể tô biển báo nguy hiểm màu tím cho đẹp.",emoji:"🎨",explain:"Sai. Mô hình phải tô đúng màu như biển thật: viền đỏ, nền vàng.",answer:!1},{id:"cn3-lam-bien-bao-06",type:"mc",q:"Muốn làm mặt biển báo cấm, em cắt bìa hình gì?",emoji:"⭕",explain:"Biển báo cấm thường hình tròn nên em cắt bìa hình tròn.",options:["Hình tròn","Hình tam giác","Hình chữ nhật","Hình trái tim"],answer:0},{id:"cn3-lam-bien-bao-07",type:"fill",q:"Em có thể dùng đất … để làm đế cho cột biển.",emoji:"🟢",explain:"Đất nặn giữ chặt chân cột nên làm đế được.",answer:["nặn"]},{id:"cn3-lam-bien-bao-08",type:"mc",q:"Em dùng gì để gắn mặt biển vào cột?",emoji:"🧴",explain:"Hồ dán hoặc băng dính giúp gắn mặt biển vào cột.",options:["Bút chì","Cục tẩy","Thước kẻ","Băng dính"],answer:3},{id:"cn3-lam-bien-bao-09",type:"tf",q:"Làm mô hình biển báo giúp em nhớ ý nghĩa của biển báo.",emoji:"🧠",explain:"Đúng. Tự tay làm giúp em nhớ hình dạng, màu sắc và ý nghĩa của biển.",answer:!0}]},{questions:[{id:"cn3-lam-bien-bao-10",type:"order",q:"Sắp xếp các bước làm mô hình biển báo.",explain:"Vẽ, cắt mặt biển, tô màu, gắn lên cột rồi cắm vào đế.",items:["Vẽ mặt biển lên bìa","Cắt mặt biển","Tô màu cho mặt biển","Gắn mặt biển lên cột","Cắm cột vào đế"]},{id:"cn3-lam-bien-bao-11",type:"mc",q:"Làm mô hình biển báo nguy hiểm, em tô màu thế nào?",emoji:"🔺",explain:"Biển báo nguy hiểm có viền đỏ, nền vàng.",options:["Viền đỏ, nền vàng","Viền xanh, nền đỏ","Nền xanh lam","Toàn màu đen"],answer:0},{id:"cn3-lam-bien-bao-12",type:"mc",q:"Làm mô hình biển hiệu lệnh, em tô nền màu gì?",emoji:"🔵",explain:"Biển hiệu lệnh có nền xanh lam.",options:["Màu vàng","Màu xanh lam","Màu hồng","Màu nâu"],answer:1},{id:"cn3-lam-bien-bao-13",type:"tf",q:"Muốn cắt hình tròn đẹp, em có thể vẽ theo miệng cốc rồi cắt.",emoji:"🥛",explain:"Đúng. Vẽ theo miệng cốc giúp có hình tròn đều.",answer:!0},{id:"cn3-lam-bien-bao-14",type:"match",q:"Nối phần của mô hình với vật liệu phù hợp.",explain:"Mặt biển dùng bìa, cột dùng ống hút, đế dùng đất nặn.",pairs:[["Mặt biển","Bìa cứng"],["Cột biển","Ống hút"],["Đế","Đất nặn"]]},{id:"cn3-lam-bien-bao-15",type:"mc",q:"Mô hình biển báo bị đổ. Lí do có thể là gì?",emoji:"↘️",explain:"Đế quá nhỏ hoặc cột cắm chưa chặt làm mô hình bị đổ.",options:["Mặt biển quá đúng","Tô màu quá đẹp","Đế quá nhỏ","Cột quá thẳng"],answer:2},{id:"cn3-lam-bien-bao-16",type:"multi",q:"Mô hình biển báo đẹp và đúng cần có gì?",explain:"Đúng hình dạng, đúng màu và đứng vững.",options:["Đúng hình dạng","Đúng màu sắc","Đứng vững","Tô màu tùy thích"],answers:[0,1,2]},{id:"cn3-lam-bien-bao-17",type:"tf",q:"Que gỗ nhỏ có đầu nhọn cần cẩn thận khi cầm và không chĩa vào bạn.",emoji:"⚠️",explain:"Đúng. Đầu que nhọn có thể làm bạn bị thương.",answer:!0},{id:"cn3-lam-bien-bao-18",type:"mc",q:"Muốn cắt mặt biển tam giác đều, em làm gì trước?",emoji:"📏",explain:"Dùng thước kẻ ba cạnh bằng nhau rồi mới cắt.",options:["Vẽ hình tròn","Kẻ ba cạnh bằng nhau","Cắt bừa một góc","Xé tay cho nhanh"],answer:1}]},{questions:[{id:"cn3-lam-bien-bao-19",type:"mc",q:"Ngọc muốn làm biển “Trẻ em” để đặt ở mô hình cổng trường. Ngọc cắt bìa hình gì?",emoji:"🚸",explain:"Biển “Trẻ em” là biển nguy hiểm, có hình tam giác.",options:["Hình tròn","Hình tam giác","Hình vuông","Hình ngôi sao"],answer:1},{id:"cn3-lam-bien-bao-20",type:"mc",q:"Dũng làm biển cấm đi ngược chiều. Dũng tô màu thế nào?",emoji:"⛔",explain:"Biển cấm đi ngược chiều hình tròn, nền đỏ, có vạch ngang màu trắng.",options:["Nền vàng, vạch đen","Nền xanh, vạch đỏ","Nền đỏ, vạch trắng","Nền trắng, vạch tím"],answer:2},{id:"cn3-lam-bien-bao-21",type:"tf",q:"Cắm cột sâu vào đất nặn giúp mô hình đứng vững hơn.",emoji:"🟢",explain:"Đúng. Cột cắm sâu, chặt thì mô hình khó đổ.",answer:!0},{id:"cn3-lam-bien-bao-22",type:"multi",q:"Mặt biển hay bị rơi khỏi cột. Em có thể làm gì?",explain:"Dán thêm băng dính hoặc kẹp mặt biển vào giữa hai nửa cột giúp chắc hơn.",options:["Dán thêm băng dính","Kẹp mặt biển chắc hơn","Đợi hồ khô rồi dựng","Bỏ luôn cột đi"],answers:[0,1,2]},{id:"cn3-lam-bien-bao-23",type:"order",q:"Sắp xếp các bước làm đế bằng đất nặn.",explain:"Nặn khối đất, ấn dẹt cho phẳng, cắm cột vào giữa rồi kiểm tra.",items:["Lấy một nắm đất nặn","Ấn dẹt cho đáy phẳng","Cắm cột vào giữa đế","Thử xem biển có đứng vững"]},{id:"cn3-lam-bien-bao-24",type:"mc",q:"Cả nhóm làm xong mô hình. Việc nào nên làm tiếp theo?",emoji:"🧹",explain:"Làm xong cần thu dọn giấy vụn, cất kéo và đồ dùng.",options:["Mang kéo đi chơi","Để giấy vụn khắp bàn","Ném đất nặn lên tường","Thu dọn, cất đồ dùng"],answer:3},{id:"cn3-lam-bien-bao-25",type:"tf",q:"Mô hình biển báo có thể dùng để chơi trò đi đường an toàn với bạn.",emoji:"🚶",explain:"Đúng. Chơi với mô hình giúp em luyện cách đi đường an toàn.",answer:!0},{id:"cn3-lam-bien-bao-26",type:"mc",q:"Biển của Thảo hình tròn, viền đỏ nhưng nền màu xanh lá. Thảo cần sửa gì?",emoji:"⭕",explain:"Biển báo cấm thường có nền trắng, Thảo cần sửa màu nền.",options:["Tô thêm màu tím","Cắt thành tam giác","Sửa nền thành trắng","Bỏ viền đỏ"],answer:2}]}],challenge:{questions:[{id:"cn3-lam-bien-bao-27",type:"mc",q:"Nhóm của An muốn làm biển báo cho xe phải đi thẳng. An cần làm mặt biển thế nào?",emoji:"⬆️",explain:"Biển hiệu lệnh hình tròn, nền xanh lam, có mũi tên trắng chỉ hướng phải đi.",options:["Tròn, nền đỏ, vạch trắng","Tam giác vàng, mũi tên","Tròn, xanh, mũi tên trắng","Vuông, chữ P trắng"],answer:2},{id:"cn3-lam-bien-bao-10",type:"order",q:"Sắp xếp các bước làm mô hình biển báo.",explain:"Vẽ, cắt mặt biển, tô màu, gắn lên cột rồi cắm vào đế.",items:["Vẽ mặt biển lên bìa","Cắt mặt biển","Tô màu cho mặt biển","Gắn mặt biển lên cột","Cắm cột vào đế"]},{id:"cn3-lam-bien-bao-28",type:"match",q:"Nối biển cần làm với hình mặt biển.",explain:"Mỗi nhóm biển có hình dạng riêng.",pairs:[["Biển “Trẻ em”","Tam giác"],["Biển cấm người đi bộ","Hình tròn"],["Biển nơi đỗ xe","Hình vuông"]]},{id:"cn3-lam-bien-bao-29",type:"tf",q:"Mô hình biển báo không cần giống biển thật, chỉ cần đẹp là được.",emoji:"🤔",explain:"Sai. Mô hình phải đúng hình dạng, màu sắc để mọi người hiểu đúng ý nghĩa.",answer:!1},{id:"cn3-lam-bien-bao-30",type:"multi",q:"Bạn nào làm mô hình an toàn?",explain:"Cầm kéo cẩn thận, không chĩa que nhọn vào bạn và rửa tay sau khi nặn là đúng.",options:["Bình đưa cán kéo cho bạn","Hà chĩa que nhọn vào bạn","Vy rửa tay sau khi nặn","Tùng nếm thử đất nặn"],answers:[0,2]},{id:"cn3-lam-bien-bao-31",type:"fill",q:"Biển hiệu lệnh có nền xanh lam và hình … .",emoji:"🔵",explain:"Biển hiệu lệnh có hình tròn.",answer:["tròn"]},{id:"cn3-lam-bien-bao-32",type:"mc",q:"Mô hình nghiêng sang một bên. Nguyên nhân có thể là gì?",emoji:"↗️",explain:"Cột cắm lệch hoặc đế không phẳng làm mô hình nghiêng.",options:["Màu tô quá đậm","Hồ dán quá khô","Mặt biển quá đúng","Cột cắm lệch"],answer:3}]},summary:["Mô hình biển báo gồm mặt biển, cột biển và đế.","Mặt biển phải đúng hình dạng và màu sắc như biển thật.","Các bước: vẽ, cắt, tô màu mặt biển, gắn lên cột, cắm vào đế cho đứng vững."]}]},{id:"lam-do-choi",title:"Làm đồ chơi",lessons:[{id:"cn3-do-choi-an-toan",title:"Chọn và chơi đồ chơi an toàn",weeks:[28,29],learn:[{title:"Đồ chơi an toàn",text:"Đồ chơi an toàn không có cạnh sắc, đầu nhọn, không bong tróc sơn và phù hợp với tuổi của người chơi.",example:"🧸 mềm, nhẵn  ·  🧩 hợp lứa tuổi"},{title:"Cẩn thận với em bé",text:"Đồ chơi có chi tiết nhỏ như hạt, viên bi, pin cúc áo không được để gần em bé, vì em bé có thể cho vào miệng.",example:"👶 ❌ viên bi  ·  ❌ pin cúc áo"},{title:"Chơi và cất đồ chơi đúng cách",text:"Em chơi đúng cách, không ném đồ chơi vào người khác. Chơi xong, em cất đồ chơi gọn gàng và báo người lớn khi đồ chơi bị hỏng.",example:"🎮 chơi đúng cách  ➜  📦 cất gọn"}],practice:[{questions:[{id:"cn3-do-choi-an-toan-01",type:"mc",q:"Đồ chơi nào an toàn hơn cho em bé?",emoji:"👶",explain:"Gấu bông mềm, không có chi tiết nhỏ nên an toàn cho em bé.",options:["Hộp viên bi nhỏ","Dao đồ chơi nhọn","Ô tô cạnh sắc","Gấu bông mềm"],answer:3},{id:"cn3-do-choi-an-toan-02",type:"tf",q:"Đồ chơi có cạnh sắc có thể làm em bị đứt tay.",emoji:"⚠️",explain:"Đúng. Cạnh sắc dễ cứa vào tay khi chơi.",answer:!0},{id:"cn3-do-choi-an-toan-03",type:"tf",q:"Em bé có thể chơi viên bi nhỏ một mình.",emoji:"🔵",explain:"Sai. Em bé có thể nuốt viên bi, rất nguy hiểm.",answer:!1},{id:"cn3-do-choi-an-toan-04",type:"multi",q:"Đồ chơi an toàn có đặc điểm nào?",explain:"Đồ chơi an toàn nhẵn, không đầu nhọn và không bong sơn.",options:["Nhẵn, không cạnh sắc","Không có đầu nhọn","Sơn không bong tróc","Có nhiều mảnh vỡ"],answers:[0,1,2]},{id:"cn3-do-choi-an-toan-05",type:"mc",q:"Chơi xong, em làm gì với đồ chơi?",emoji:"📦",explain:"Cất đồ chơi gọn gàng để không ai bị vấp ngã và đồ chơi bền hơn.",options:["Cất gọn gàng","Vứt khắp nhà","Ném ra ngoài sân","Để trên cầu thang"],answer:0},{id:"cn3-do-choi-an-toan-06",type:"fill",q:"Đồ chơi bị hỏng, em báo cho người … biết.",emoji:"🙋",explain:"Người lớn sẽ sửa hoặc bỏ đồ chơi hỏng cho an toàn.",answer:["lớn"]},{id:"cn3-do-choi-an-toan-07",type:"mc",q:"Vì sao không để pin cúc áo gần em bé?",emoji:"🔋",explain:"Em bé có thể nuốt pin cúc áo, rất nguy hiểm.",options:["Pin làm em bé cười","Em bé có thể nuốt","Pin có mùi thơm","Pin quá to"],answer:1},{id:"cn3-do-choi-an-toan-08",type:"tf",q:"Ném đồ chơi vào người khác là cách chơi không an toàn.",emoji:"🚫",explain:"Đúng. Đồ chơi ném trúng có thể làm người khác bị đau.",answer:!0},{id:"cn3-do-choi-an-toan-09",type:"mc",q:"Đồ chơi để trên lối đi có thể gây ra điều gì?",emoji:"🚶",explain:"Đồ chơi trên lối đi dễ làm người khác vấp ngã.",options:["Làm nhà đẹp hơn","Làm đồ chơi mới","Làm người vấp ngã","Không sao cả"],answer:2}]},{questions:[{id:"cn3-do-choi-an-toan-10",type:"match",q:"Nối đồ chơi chưa an toàn với lí do.",explain:"Mỗi đồ chơi có một điểm nguy hiểm cần tránh.",pairs:[["Ô tô gãy cạnh sắc","Dễ đứt tay"],["Viên bi nhỏ","Em bé dễ nuốt"],["Đồ chơi bong sơn","Bụi sơn bám tay"]]},{id:"cn3-do-choi-an-toan-11",type:"mc",q:"Trên vỏ hộp đồ chơi ghi lứa tuổi phù hợp để làm gì?",emoji:"📦",explain:"Ghi lứa tuổi giúp chọn đồ chơi hợp với người chơi, an toàn hơn.",options:["Để hộp đẹp hơn","Để chọn đúng tuổi","Để đồ chơi đắt hơn","Để chơi nhanh hơn"],answer:1},{id:"cn3-do-choi-an-toan-12",type:"tf",q:"Đồ chơi dành cho anh chị lớn đều an toàn cho em bé.",emoji:"👶",explain:"Sai. Đồ chơi của trẻ lớn có thể có chi tiết nhỏ không hợp với em bé.",answer:!1},{id:"cn3-do-choi-an-toan-13",type:"multi",q:"Cách chơi nào là an toàn?",explain:"Chơi đúng cách, chơi ở chỗ rộng, không ném và không đưa đồ chơi lên miệng.",options:["Chơi ở chỗ rộng rãi","Chơi đúng cách","Ném đồ chơi vào bạn","Ngậm đồ chơi trong miệng"],answers:[0,1]},{id:"cn3-do-choi-an-toan-14",type:"mc",q:"Em thấy viên bi rơi gần chỗ em bé chơi. Em nên làm gì?",emoji:"🔵",explain:"Nhặt viên bi cất đi để em bé không nuốt phải.",options:["Mặc kệ viên bi","Đưa cho em bé","Đá viên bi đi","Nhặt lên cất đi"],answer:3},{id:"cn3-do-choi-an-toan-15",type:"tf",q:"Đồ chơi dùng pin nên để người lớn thay pin.",emoji:"🔋",explain:"Đúng. Người lớn thay pin và cất pin cũ đúng chỗ cho an toàn.",answer:!0},{id:"cn3-do-choi-an-toan-16",type:"mc",q:"Vì sao nên rửa tay sau khi chơi đồ chơi?",emoji:"🧼",explain:"Đồ chơi có bụi bẩn, rửa tay giúp em sạch sẽ, khỏe mạnh.",options:["Để tay sạch sẽ","Để đồ chơi mới","Để chơi tiếp","Để tay ướt"],answer:0},{id:"cn3-do-choi-an-toan-17",type:"mc",q:"Đồ chơi bị nứt, có mảnh nhọn chìa ra. Em nên làm gì?",emoji:"⚠️",explain:"Ngừng chơi và đưa cho người lớn xem để sửa hoặc bỏ đi.",options:["Tiếp tục chơi","Tặng cho em bé","Bẻ mảnh nhọn ra","Đưa người lớn xem"],answer:3},{id:"cn3-do-choi-an-toan-18",type:"tf",q:"Chơi đồ chơi gần bếp đang nấu là an toàn.",emoji:"🔥",explain:"Sai. Gần bếp nóng rất dễ bị bỏng, em chơi ở chỗ khác.",answer:!1}]},{questions:[{id:"cn3-do-choi-an-toan-19",type:"mc",q:"Chi muốn tặng em bé 1 tuổi một món đồ chơi. Chi nên chọn món nào?",emoji:"🎁",explain:"Quả bóng vải mềm, to, không có chi tiết nhỏ hợp với em bé.",options:["Bộ xếp hình hạt nhỏ","Ô tô có pin cúc áo","Hộp viên bi","Quả bóng vải mềm"],answer:3},{id:"cn3-do-choi-an-toan-20",type:"multi",q:"Tình huống nào có thể nguy hiểm?",explain:"Em bé cầm viên bi, đồ chơi trên cầu thang và chơi gần bếp đều nguy hiểm.",options:["Em bé cầm viên bi","Đồ chơi trên cầu thang","Chơi gần bếp nóng","Cất đồ chơi vào hộp"],answers:[0,1,2]},{id:"cn3-do-choi-an-toan-21",type:"tf",q:"Chơi xong cất đồ chơi giúp đồ chơi bền và nhà gọn gàng.",emoji:"🏠",explain:"Đúng. Cất gọn giúp đồ chơi không bị dẫm hỏng, nhà sạch đẹp.",answer:!0},{id:"cn3-do-choi-an-toan-22",type:"order",q:"Sắp xếp các việc khi chơi đồ chơi.",explain:"Kiểm tra đồ chơi, chơi đúng cách, cất gọn rồi rửa tay.",items:["Kiểm tra đồ chơi còn tốt","Chơi đúng cách, ở chỗ rộng","Cất đồ chơi gọn gàng","Rửa tay sạch sẽ"]},{id:"cn3-do-choi-an-toan-23",type:"mc",q:"Nam thấy em mình đang ngậm một chi tiết đồ chơi. Nam nên làm gì?",emoji:"👶",explain:"Nam gọi ngay người lớn để giúp em bé an toàn.",options:["Chờ em tự nhổ ra","Cười rồi bỏ đi","Đưa thêm đồ chơi","Gọi ngay người lớn"],answer:3},{id:"cn3-do-choi-an-toan-24",type:"tf",q:"Chia sẻ đồ chơi và chơi cùng bạn vui vẻ là việc tốt.",emoji:"🤝",explain:"Đúng. Chơi cùng nhau vui vẻ, nhường nhịn giúp tình bạn đẹp hơn.",answer:!0},{id:"cn3-do-choi-an-toan-25",type:"match",q:"Nối tình huống với việc nên làm.",explain:"Mỗi tình huống có một cách xử lí an toàn.",pairs:[["Đồ chơi bị hỏng","Báo người lớn"],["Chơi xong","Cất gọn gàng"],["Có em bé gần","Cất chi tiết nhỏ"]]},{id:"cn3-do-choi-an-toan-26",type:"mc",q:"Khoa có súng nước. Cách chơi nào đúng?",emoji:"💦",explain:"Chơi ở sân, không bắn vào mắt hay vào người không muốn chơi.",options:["Bắn vào mắt bạn","Chơi ở sân, nhẹ nhàng","Bắn vào ổ điện","Bắn vào người già"],answer:1}]}],challenge:{questions:[{id:"cn3-do-choi-an-toan-27",type:"mc",q:"Vì sao đồ chơi có chi tiết nhỏ ghi “không dành cho trẻ dưới 3 tuổi”?",emoji:"📦",explain:"Trẻ nhỏ hay cho đồ vào miệng nên có thể nuốt chi tiết nhỏ.",options:["Đồ chơi quá to","Trẻ nhỏ chơi giỏi","Trẻ nhỏ dễ nuốt","Đồ chơi quá rẻ"],answer:2},{id:"cn3-do-choi-an-toan-20",type:"multi",q:"Tình huống nào có thể nguy hiểm?",explain:"Em bé cầm viên bi, đồ chơi trên cầu thang và chơi gần bếp đều nguy hiểm.",options:["Em bé cầm viên bi","Đồ chơi trên cầu thang","Chơi gần bếp nóng","Cất đồ chơi vào hộp"],answers:[0,1,2]},{id:"cn3-do-choi-an-toan-28",type:"tf",q:"Đồ chơi bị bong sơn vẫn có thể ngậm vào miệng.",emoji:"🎨",explain:"Sai. Sơn bong có thể dính vào miệng, không an toàn.",answer:!1},{id:"cn3-do-choi-an-toan-29",type:"mc",q:"Lan có ô tô đồ chơi bị gãy, lộ cạnh sắc. Cách làm nào đúng nhất?",emoji:"🚗",explain:"Ngừng chơi và nhờ người lớn sửa hoặc bỏ đi đúng chỗ.",options:["Tặng cho em bé","Tiếp tục chơi","Giấu dưới gầm giường","Nhờ người lớn xử lí"],answer:3},{id:"cn3-do-choi-an-toan-30",type:"fill",q:"Đồ chơi an toàn không có cạnh … .",emoji:"🧸",explain:"Đồ chơi an toàn không có cạnh sắc.",answer:["sắc"]},{id:"cn3-do-choi-an-toan-31",type:"multi",q:"Đồ chơi nào cần cất xa em bé?",explain:"Viên bi, pin cúc áo và hạt chuỗi nhỏ đều dễ bị nuốt.",options:["Viên bi","Pin cúc áo","Hạt chuỗi nhỏ","Gấu bông to"],answers:[0,1,2]},{id:"cn3-do-choi-an-toan-22",type:"order",q:"Sắp xếp các việc khi chơi đồ chơi.",explain:"Kiểm tra đồ chơi, chơi đúng cách, cất gọn rồi rửa tay.",items:["Kiểm tra đồ chơi còn tốt","Chơi đúng cách, ở chỗ rộng","Cất đồ chơi gọn gàng","Rửa tay sạch sẽ"]}]},summary:["Đồ chơi an toàn không có cạnh sắc, đầu nhọn, không bong sơn và hợp với tuổi người chơi.","Chi tiết nhỏ như viên bi, pin cúc áo phải để xa em bé.","Chơi đúng cách, chơi xong cất gọn, đồ chơi hỏng thì báo người lớn."]},{id:"cn3-do-choi-giay",title:"Làm đồ chơi từ giấy",weeks:[30,32],learn:[{title:"Đồ chơi từ giấy",text:"Chỉ với tờ giấy, em có thể gấp máy bay, thuyền, con ếch và nhiều đồ chơi khác.",example:"✈️ máy bay  ·  ⛵ thuyền  ·  🐸 con ếch"},{title:"Gấp giấy cho đẹp",text:"Chọn tờ giấy phẳng, gấp từng bước theo hướng dẫn. Mỗi nếp gấp miết thật thẳng, các mép giấy trùng khít nhau.",example:"📄 gấp đôi  ➜  👆 miết thẳng  ➜  ✈️"},{title:"Chơi an toàn",text:"Phóng máy bay giấy ở chỗ rộng, không phóng vào mặt bạn. Thả thuyền giấy ở chậu nước, có người lớn ở bên, không ra ao hồ một mình.",example:"✈️ chỗ rộng  ·  ⛵ chậu nước  ·  👨‍👩‍👧 người lớn"}],practice:[{questions:[{id:"cn3-do-choi-giay-01",type:"mc",q:"Vật liệu chính để gấp máy bay giấy là gì?",emoji:"✈️",explain:"Máy bay giấy được gấp từ một tờ giấy.",options:["Tờ giấy","Đất nặn","Vỏ chai","Que gỗ"],answer:0},{id:"cn3-do-choi-giay-02",type:"multi",q:"Đồ chơi nào có thể gấp từ giấy?",explain:"Máy bay, thuyền và con ếch đều gấp được từ giấy.",options:["Máy bay","Thuyền","Con ếch","Xe đạp thật"],answers:[0,1,2]},{id:"cn3-do-choi-giay-03",type:"tf",q:"Nếp gấp miết thẳng giúp đồ chơi giấy đẹp hơn.",emoji:"👆",explain:"Đúng. Nếp gấp thẳng, rõ thì sản phẩm gọn và đẹp.",answer:!0},{id:"cn3-do-choi-giay-04",type:"tf",q:"Tờ giấy nhàu nát, rách sẽ gấp được máy bay bay xa nhất.",emoji:"📄",explain:"Sai. Giấy phẳng, lành mới gấp đẹp và bay tốt.",answer:!1},{id:"cn3-do-choi-giay-05",type:"mc",q:"Nên phóng máy bay giấy ở đâu?",emoji:"🏞️",explain:"Phóng ở chỗ rộng, không có người đứng phía trước.",options:["Ở chỗ rộng rãi","Gần đường xe chạy","Trên mái nhà","Vào mặt bạn"],answer:0},{id:"cn3-do-choi-giay-06",type:"fill",q:"Khi gấp giấy, em gấp lần lượt từng … theo hướng dẫn.",emoji:"📄",explain:"Gấp lần lượt từng bước thì sản phẩm mới đúng.",answer:["bước"]},{id:"cn3-do-choi-giay-07",type:"mc",q:"Thả thuyền giấy ở đâu là an toàn?",emoji:"⛵",explain:"Thả thuyền ở chậu nước, có người lớn bên cạnh.",options:["Ở chậu nước","Ở sông lớn","Ở ao sâu một mình","Ở giếng nước"],answer:0},{id:"cn3-do-choi-giay-08",type:"tf",q:"Gấp đồ chơi từ giấy giúp đôi tay em khéo léo hơn.",emoji:"🙌",explain:"Đúng. Gấp giấy luyện cho tay khéo và tính kiên nhẫn.",answer:!0},{id:"cn3-do-choi-giay-09",type:"mc",q:"Gấp xong máy bay, em có thể làm gì cho đẹp?",emoji:"🎨",explain:"Em vẽ, tô màu trang trí cho máy bay đẹp hơn.",options:["Vẽ, tô màu","Ngâm vào nước","Xé đôi ra","Vò lại"],answer:0}]},{questions:[{id:"cn3-do-choi-giay-10",type:"order",q:"Sắp xếp các việc khi làm đồ chơi từ giấy.",explain:"Chọn giấy, gấp theo từng bước, trang trí rồi chơi thử.",items:["Chọn tờ giấy phẳng","Gấp lần lượt từng bước","Trang trí sản phẩm","Chơi thử đồ chơi"]},{id:"cn3-do-choi-giay-11",type:"mc",q:"Vì sao khi gấp đôi, hai mép giấy phải trùng khít nhau?",emoji:"📄",explain:"Mép trùng khít thì hai bên đều nhau, đồ chơi cân đối.",options:["Để giấy nặng hơn","Để giấy rách","Để giấy đổi màu","Để hai bên đều nhau"],answer:3},{id:"cn3-do-choi-giay-12",type:"tf",q:"Máy bay giấy có hai cánh lệch nhau sẽ bay thẳng hơn.",emoji:"✈️",explain:"Sai. Hai cánh đều nhau thì máy bay mới bay thẳng.",answer:!1},{id:"cn3-do-choi-giay-13",type:"match",q:"Nối đồ chơi giấy với cách chơi.",explain:"Máy bay để phóng, thuyền để thả nước, con ếch để ấn cho bật nhảy.",pairs:[["Máy bay giấy","Phóng bay"],["Thuyền giấy","Thả trên nước"],["Ếch giấy","Ấn cho bật nhảy"]]},{id:"cn3-do-choi-giay-14",type:"mc",q:"Thuyền giấy để lâu trong nước sẽ thế nào?",emoji:"⛵",explain:"Giấy thấm nước nên thuyền dần mềm ra và chìm.",options:["Cứng hơn","Đổi thành gỗ","Bay lên trời","Ngấm nước, chìm"],answer:3},{id:"cn3-do-choi-giay-15",type:"multi",q:"Khi chơi máy bay giấy, việc nào an toàn?",explain:"Phóng ở chỗ rộng, nhìn trước khi phóng và không phóng vào người.",options:["Phóng ở chỗ rộng","Nhìn trước khi phóng","Phóng vào mắt bạn","Trèo cao để phóng"],answers:[0,1]},{id:"cn3-do-choi-giay-16",type:"tf",q:"Giấy báo cũ hoặc giấy nháp đã dùng có thể tận dụng để gấp đồ chơi.",emoji:"♻️",explain:"Đúng. Tận dụng giấy cũ giúp tiết kiệm.",answer:!0},{id:"cn3-do-choi-giay-17",type:"mc",q:"Máy bay giấy rơi lên mái nhà. Em nên làm gì?",emoji:"🏠",explain:"Không trèo lên mái, nhờ người lớn hoặc gấp chiếc khác.",options:["Trèo lên lấy","Ném đá lên mái","Nhờ người lớn","Leo cây để lấy"],answer:2},{id:"cn3-do-choi-giay-18",type:"mc",q:"Giấy hình vuông có mấy cạnh bằng nhau?",emoji:"🟥",explain:"Hình vuông có 4 cạnh bằng nhau.",options:["2 cạnh","5 cạnh","3 cạnh","4 cạnh"],answer:3}]},{questions:[{id:"cn3-do-choi-giay-19",type:"mc",q:"Máy bay của Phúc cứ bay lệch sang trái. Phúc nên kiểm tra gì?",emoji:"✈️",explain:"Hai cánh không đều làm máy bay lệch; Phúc chỉnh lại cho hai cánh bằng nhau.",options:["Hai cánh có đều","Màu của giấy","Tên của máy bay","Giờ phóng bay"],answer:0},{id:"cn3-do-choi-giay-20",type:"mc",q:"Vy muốn thuyền giấy nổi lâu hơn. Vy có thể chọn giấy nào?",emoji:"⛵",explain:"Giấy dày, có lớp phủ bóng ít thấm nước hơn giấy ăn.",options:["Giấy ăn mỏng","Giấy dày, bóng","Giấy đã ướt","Giấy bị rách"],answer:1},{id:"cn3-do-choi-giay-21",type:"tf",q:"Khi thả thuyền giấy ở chậu nước, em vẫn cần có người lớn ở bên.",emoji:"👨‍👩‍👧",explain:"Đúng. Chơi với nước luôn cần người lớn trông.",answer:!0},{id:"cn3-do-choi-giay-22",type:"order",q:"Sắp xếp các bước bắt đầu gấp một máy bay giấy đơn giản.",explain:"Gấp đôi tờ giấy lấy nếp giữa, mở ra, gấp hai góc trên vào nếp giữa rồi gấp tiếp hai cánh.",items:["Gấp đôi tờ giấy lấy nếp giữa","Mở ra, gấp hai góc trên vào nếp giữa","Gấp đôi theo nếp giữa","Gấp hai bên xuống thành cánh"]},{id:"cn3-do-choi-giay-23",type:"multi",q:"Làm gì để đồ chơi giấy gấp đẹp?",explain:"Giấy phẳng, gấp đúng bước, miết thẳng nếp là cách gấp đẹp.",options:["Dùng giấy phẳng","Gấp đúng từng bước","Miết thẳng nếp gấp","Gấp vội không nhìn"],answers:[0,1,2]},{id:"cn3-do-choi-giay-24",type:"tf",q:"Chơi máy bay giấy cạnh đường có xe chạy là an toàn.",emoji:"🚗",explain:"Sai. Chạy theo máy bay ra đường rất nguy hiểm.",answer:!1},{id:"cn3-do-choi-giay-25",type:"mc",q:"Gấp xong, sàn nhà có nhiều giấy vụn. Em làm gì?",emoji:"🧹",explain:"Nhặt giấy vụn bỏ vào thùng rác cho nhà sạch.",options:["Nhặt bỏ thùng rác","Đá vào gầm tủ","Để mẹ dọn","Thổi bay đi"],answer:0},{id:"cn3-do-choi-giay-26",type:"mc",q:"Bình và Minh thi phóng máy bay. Cách chơi nào đẹp?",emoji:"🤝",explain:"Thay phiên nhau phóng, vui vẻ dù thắng hay thua.",options:["Thay phiên, vui vẻ","Giành máy bay bạn","Xé máy bay bạn","Phóng vào người bạn"],answer:0}]}],challenge:{questions:[{id:"cn3-do-choi-giay-27",type:"mc",q:"Hai máy bay gấp giống nhau. Chiếc nào thường bay tốt hơn?",emoji:"✈️",explain:"Chiếc có nếp gấp thẳng, hai cánh đều nhau sẽ bay ổn định hơn.",options:["Chiếc bị nhàu","Chiếc cánh lệch","Chiếc bị ướt","Chiếc cánh đều"],answer:3},{id:"cn3-do-choi-giay-22",type:"order",q:"Sắp xếp các bước bắt đầu gấp một máy bay giấy đơn giản.",explain:"Gấp đôi tờ giấy lấy nếp giữa, mở ra, gấp hai góc trên vào nếp giữa rồi gấp tiếp hai cánh.",items:["Gấp đôi tờ giấy lấy nếp giữa","Mở ra, gấp hai góc trên vào nếp giữa","Gấp đôi theo nếp giữa","Gấp hai bên xuống thành cánh"]},{id:"cn3-do-choi-giay-28",type:"multi",q:"Bạn nào chơi đồ chơi giấy an toàn?",explain:"Phóng ở sân rộng và thả thuyền khi có mẹ bên cạnh là an toàn.",options:["An phóng ở sân rộng","Lan thả thuyền cùng mẹ","Tùng ra ao một mình","Hà phóng vào mặt bạn"],answers:[0,1]},{id:"cn3-do-choi-giay-29",type:"tf",q:"Giấy thấm nước nhanh không phù hợp để làm thuyền thả nước.",emoji:"💧",explain:"Đúng. Giấy thấm nhanh làm thuyền mau chìm.",answer:!0},{id:"cn3-do-choi-giay-30",type:"fill",q:"Muốn máy bay bay thẳng, hai … phải đều nhau.",emoji:"✈️",explain:"Hai cánh đều nhau giúp máy bay bay thẳng.",answer:["cánh"]},{id:"cn3-do-choi-giay-31",type:"match",q:"Nối vấn đề với cách sửa.",explain:"Mỗi vấn đề của đồ chơi giấy có cách sửa phù hợp.",pairs:[["Máy bay bay lệch","Chỉnh hai cánh đều"],["Thuyền chìm nhanh","Dùng giấy dày hơn"],["Nếp gấp xấu","Miết nếp thẳng"]]},{id:"cn3-do-choi-giay-32",type:"mc",q:"Thảo muốn gấp con ếch nhảy được xa. Thảo nên làm gì?",emoji:"🐸",explain:"Gấp đúng bước, nếp chắc và dùng giấy hơi cứng giúp ếch bật tốt hơn.",options:["Dùng giấy ướt","Xé bớt chân ếch","Gấp vội vàng","Gấp kĩ, nếp chắc"],answer:3}]},summary:["Từ tờ giấy, em có thể gấp máy bay, thuyền, con ếch và nhiều đồ chơi khác.","Gấp lần lượt từng bước, mép giấy trùng khít, nếp gấp miết thẳng.","Phóng máy bay ở chỗ rộng; chơi với nước phải có người lớn bên cạnh."]},{id:"cn3-do-choi-tai-che",title:"Làm đồ chơi từ vật liệu tái chế",weeks:[33,35],learn:[{title:"Vật liệu tái chế",text:"Vỏ hộp sữa, chai nhựa, nắp chai, lõi giấy đã dùng xong có thể làm thành đồ chơi. Nhớ rửa sạch, phơi khô trước khi làm.",example:"🧃 vỏ hộp  ·  🍼 chai nhựa  ·  🔘 nắp chai  ·  🧻 lõi giấy"},{title:"Ô tô từ vỏ hộp",text:"Vỏ hộp làm thân xe, nắp chai làm bánh xe, que tre nhỏ hoặc ống hút làm trục bánh. Chỗ cần đục lỗ thì nhờ người lớn giúp.",example:"🧃 thân xe  +  🔘🔘 bánh  +  🥢 trục  =  🚗"},{title:"Lợi ích của đồ chơi tái chế",text:"Làm đồ chơi từ vật liệu tái chế giúp giảm rác thải, tiết kiệm và giúp em sáng tạo.",example:"♻️ ít rác  ·  💡 sáng tạo"}],practice:[{questions:[{id:"cn3-do-choi-tai-che-01",type:"multi",q:"Vật nào có thể tái chế làm đồ chơi?",explain:"Vỏ hộp sữa, nắp chai, lõi giấy sạch đều dùng được.",options:["Vỏ hộp sữa","Nắp chai","Lõi giấy","Mảnh kính vỡ"],answers:[0,1,2]},{id:"cn3-do-choi-tai-che-02",type:"mc",q:"Làm ô tô từ vỏ hộp, em dùng gì làm bánh xe?",emoji:"🔘",explain:"Nắp chai tròn, cứng nên làm bánh xe tốt.",options:["Lá cây","Giấy ăn","Nắp chai","Cục tẩy"],answer:2},{id:"cn3-do-choi-tai-che-03",type:"tf",q:"Vỏ hộp sữa cần rửa sạch, phơi khô trước khi làm đồ chơi.",emoji:"🧃",explain:"Đúng. Vỏ hộp sạch không có mùi hôi, không bẩn tay.",answer:!0},{id:"cn3-do-choi-tai-che-04",type:"mc",q:"Làm đồ chơi từ đồ cũ giúp ích gì?",emoji:"♻️",explain:"Dùng lại đồ cũ giúp giảm rác và tiết kiệm.",options:["Tăng rác thải","Tốn nhiều tiền","Làm nhà bẩn","Giảm rác thải"],answer:3},{id:"cn3-do-choi-tai-che-05",type:"tf",q:"Khi cần đục lỗ trên nắp chai, em tự dùng dao nhọn.",emoji:"🔪",explain:"Sai. Đục lỗ cần nhờ người lớn giúp để tránh bị thương.",answer:!1},{id:"cn3-do-choi-tai-che-06",type:"fill",q:"Vỏ hộp, chai nhựa đã dùng có thể … chế thành đồ chơi.",emoji:"♻️",explain:"Tái chế là dùng lại đồ cũ để làm thành đồ mới.",answer:["tái"]},{id:"cn3-do-choi-tai-che-07",type:"mc",q:"Bộ phận nào giúp bánh xe ô tô đồ chơi quay được?",emoji:"🥢",explain:"Trục bánh xuyên qua thân xe, giúp bánh quay.",options:["Màu sơn","Cửa sổ xe","Trục bánh","Đèn xe"],answer:2},{id:"cn3-do-choi-tai-che-08",type:"mc",q:"Ô tô đồ chơi làm từ vỏ hộp thường có mấy bánh xe?",emoji:"🚗",explain:"Ô tô thường có 4 bánh, mỗi bên 2 bánh.",options:["1 bánh","4 bánh","Không bánh","2 bánh"],answer:1},{id:"cn3-do-choi-tai-che-09",type:"tf",q:"Lõi giấy vệ sinh có thể làm ống nhòm đồ chơi.",emoji:"🔭",explain:"Đúng. Ghép hai lõi giấy cạnh nhau là có ống nhòm đồ chơi.",answer:!0}]},{questions:[{id:"cn3-do-choi-tai-che-10",type:"order",q:"Sắp xếp các bước làm ô tô từ vỏ hộp.",explain:"Chuẩn bị vật liệu sạch, nhờ người lớn đục lỗ, lắp trục và bánh, rồi trang trí.",items:["Rửa sạch, phơi khô vỏ hộp và nắp chai","Nhờ người lớn đục lỗ","Lắp trục và bánh xe","Trang trí chiếc ô tô"]},{id:"cn3-do-choi-tai-che-11",type:"match",q:"Nối vật liệu với bộ phận của ô tô đồ chơi.",explain:"Vỏ hộp làm thân, nắp chai làm bánh, ống hút làm trục.",pairs:[["Vỏ hộp","Thân xe"],["Nắp chai","Bánh xe"],["Ống hút","Trục bánh"]]},{id:"cn3-do-choi-tai-che-12",type:"mc",q:"Vì sao lỗ trục ở hai bên thân xe phải ngang nhau?",emoji:"🚗",explain:"Lỗ ngang nhau thì trục thẳng, xe không bị nghiêng, chạy đều.",options:["Để xe đổi màu","Để xe không nghiêng","Để xe nặng hơn","Để xe có tiếng kêu"],answer:1},{id:"cn3-do-choi-tai-che-13",type:"tf",q:"Chai nhựa có miệng cắt sắc cần nhờ người lớn dán băng dính cho an toàn.",emoji:"🍼",explain:"Đúng. Dán mép cắt giúp không bị cứa tay.",answer:!0},{id:"cn3-do-choi-tai-che-14",type:"multi",q:"Trước khi làm đồ chơi tái chế, em cần làm gì?",explain:"Chọn vật liệu sạch, khô, còn tốt và chuẩn bị dụng cụ.",options:["Rửa sạch vật liệu","Phơi khô vật liệu","Chuẩn bị dụng cụ","Dùng hộp còn sữa thừa"],answers:[0,1,2]},{id:"cn3-do-choi-tai-che-15",type:"mc",q:"Bánh xe bị kẹt, không quay. Lí do có thể là gì?",emoji:"🔘",explain:"Bánh ép sát thân xe quá chặt nên không quay được.",options:["Bánh ép sát thân xe","Xe tô màu đỏ","Xe có tên riêng","Thân xe sạch sẽ"],answer:0},{id:"cn3-do-choi-tai-che-16",type:"tf",q:"Hộp sữa còn sữa thừa bên trong vẫn làm đồ chơi được ngay.",emoji:"🧃",explain:"Sai. Sữa thừa sẽ bị hôi, phải rửa sạch và phơi khô trước.",answer:!1},{id:"cn3-do-choi-tai-che-17",type:"mc",q:"Từ chai nhựa sạch, em có thể làm đồ chơi gì?",emoji:"🍼",explain:"Chai nhựa có thể làm con lật đật, bình hoa, chuông gió và nhiều đồ khác.",options:["Quả trứng","Bánh mì","Chuông gió","Bát canh"],answer:2},{id:"cn3-do-choi-tai-che-18",type:"mc",q:"Làm xong đồ chơi, phần vật liệu thừa nên để đâu?",emoji:"🗑️",explain:"Thứ còn dùng được thì cất đi, rác thì bỏ đúng thùng.",options:["Ném vào bạn","Vứt ra đường","Để đầy bàn học","Cất đi hoặc bỏ đúng chỗ"],answer:3}]},{questions:[{id:"cn3-do-choi-tai-che-19",type:"mc",q:"Ô tô của An chạy bị lệch. An nên kiểm tra gì?",emoji:"🚗",explain:"Trục lệch hoặc bánh to nhỏ khác nhau làm xe chạy lệch.",options:["Tên của xe","Trục và bánh xe","Màu của xe","Hình dán trên xe"],answer:1},{id:"cn3-do-choi-tai-che-20",type:"multi",q:"Vì sao nên làm đồ chơi từ vật liệu tái chế?",explain:"Đồ chơi tái chế giúp giảm rác, tiết kiệm và giúp em sáng tạo.",options:["Giảm rác thải","Tiết kiệm tiền","Giúp em sáng tạo","Làm môi trường bẩn"],answers:[0,1,2]},{id:"cn3-do-choi-tai-che-21",type:"tf",q:"Bốn bánh xe to bằng nhau giúp ô tô đồ chơi chạy thẳng hơn.",emoji:"🔘",explain:"Đúng. Bánh đều nhau thì xe không bị nghiêng lệch.",answer:!0},{id:"cn3-do-choi-tai-che-22",type:"mc",q:"Minh muốn làm con lật đật từ vỏ trứng nhựa. Phần nào nên làm nặng?",emoji:"🥚",explain:"Phần đáy nặng giúp con lật đật tự đứng dậy khi bị đẩy.",options:["Phần đầu","Phần tay","Phần đáy","Không phần nào"],answer:2},{id:"cn3-do-choi-tai-che-23",type:"order",q:"Sắp xếp các bước làm ống nhòm từ lõi giấy.",explain:"Chuẩn bị hai lõi giấy, dán cạnh nhau, gắn dây đeo rồi trang trí.",items:["Chuẩn bị hai lõi giấy","Dán hai lõi cạnh nhau","Gắn dây đeo","Trang trí ống nhòm"]},{id:"cn3-do-choi-tai-che-24",type:"tf",q:"Em có thể dùng mảnh lon nhôm sắc để làm cánh chong chóng.",emoji:"⚠️",explain:"Sai. Mảnh lon sắc dễ làm đứt tay, nên dùng giấy hoặc nhựa mềm.",answer:!1},{id:"cn3-do-choi-tai-che-25",type:"match",q:"Nối vật liệu tái chế với đồ chơi có thể làm.",explain:"Mỗi vật liệu cũ có thể làm một đồ chơi phù hợp.",pairs:[["Vỏ hộp sữa","Ô tô"],["Lõi giấy","Ống nhòm"],["Chai nhựa","Chuông gió"]]},{id:"cn3-do-choi-tai-che-26",type:"mc",q:"Ngọc làm xong ô tô và muốn khoe. Ngọc nên giới thiệu điều gì?",emoji:"🗣️",explain:"Ngọc giới thiệu vật liệu đã dùng, cách làm và cách chơi.",options:["Vật liệu, cách làm","Giá tiền đồ chơi","Chê xe của bạn","Không nói gì"],answer:0}]}],challenge:{questions:[{id:"cn3-do-choi-tai-che-27",type:"mc",q:"Bánh xe ô tô của Hà quay nhưng xe không chạy. Lí do có thể là gì?",emoji:"🚗",explain:"Bánh không chạm đất vì thân xe thấp, quệt xuống sàn.",options:["Thân xe quệt sàn","Xe tô màu xanh","Xe có cửa sổ","Bánh xe tròn đều"],answer:0},{id:"cn3-do-choi-tai-che-10",type:"order",q:"Sắp xếp các bước làm ô tô từ vỏ hộp.",explain:"Chuẩn bị vật liệu sạch, nhờ người lớn đục lỗ, lắp trục và bánh, rồi trang trí.",items:["Rửa sạch, phơi khô vỏ hộp và nắp chai","Nhờ người lớn đục lỗ","Lắp trục và bánh xe","Trang trí chiếc ô tô"]},{id:"cn3-do-choi-tai-che-28",type:"multi",q:"Việc nào cần nhờ người lớn giúp?",explain:"Đục lỗ nắp chai và cắt chai nhựa cần người lớn làm; tô màu em tự làm được.",options:["Đục lỗ nắp chai","Cắt chai nhựa","Tô màu thân xe","Dán hình trang trí"],answers:[0,1]},{id:"cn3-do-choi-tai-che-29",type:"tf",q:"Đồ chơi tái chế cũng cần an toàn: không có cạnh sắc, không có chi tiết dễ rời cho em bé.",emoji:"🧸",explain:"Đúng. Đồ chơi tự làm cũng phải an toàn như đồ chơi mua.",answer:!0},{id:"cn3-do-choi-tai-che-30",type:"fill",q:"Trục bánh xe phải … để xe không bị nghiêng.",emoji:"🥢",explain:"Trục thẳng thì hai bánh ngang nhau, xe chạy vững.",answer:["thẳng"]},{id:"cn3-do-choi-tai-che-31",type:"match",q:"Nối vấn đề với cách sửa.",explain:"Mỗi lỗi của ô tô đồ chơi có cách sửa phù hợp.",pairs:[["Bánh xe bị kẹt","Nới bánh xa thân"],["Xe chạy lệch","Chỉnh trục cho thẳng"],["Vỏ hộp có mùi","Rửa sạch, phơi khô"]]},{id:"cn3-do-choi-tai-che-32",type:"mc",q:"Lớp em muốn làm đồ chơi tặng các em nhỏ. Cách làm nào hợp lí nhất?",emoji:"🎁",explain:"Dùng vật liệu sạch, an toàn, không chi tiết nhỏ và nhờ thầy cô kiểm tra.",options:["Dùng đồ sạch, an toàn","Dùng mảnh kính màu","Gắn nhiều hạt nhỏ","Dùng hộp còn sữa"],answer:0}]},summary:["Vỏ hộp, chai nhựa, nắp chai, lõi giấy sạch có thể làm thành đồ chơi.","Rửa sạch, phơi khô vật liệu; việc đục lỗ, cắt chai phải nhờ người lớn.","Đồ chơi tái chế giúp giảm rác, tiết kiệm và giúp em sáng tạo."]}]}],a={grade:3,subject:n,title:i,review:h,cid:t,topics:c};export{t as cid,a as default,g as grade,h as review,n as subject,i as title,c as topics};
